WoWFQ[93022] = { t = "آتش؛ تنها راه مطمئن", d = "اسیران باید نجات پیدا کنند، آره، اما این مکان یک ظلم‌فرهنگ است.\nباید با آتشِ روح‌زادهٔ Jan'alai پاکش کنیم.\nاین totem را بردار. به تو اجازه می‌دهد نفس loa ما را به کار بگیری.\nلانه‌هایشان را بسوزان. و آن خواهرانِ بدجنسِ تخم‌گذار را بکش!", o = { "Spiteful Broodsister کشته‌شده", "پاک‌سازی Blistering Terrace" }, p = "تخم‌ها و مرغ‌هایی که تخم گذاشته‌اند را سرخ کردی؟", c = "شکر که Jan'alai ما را لایق برکتش دید.\nشکر که ارادهٔ hash'ey انجام شد!" }
WoWFQ[93023] = { t = "مرگ خشم‌ها", d = "حالا فقط این موجودها سر راه ما تا... هستند\n<Zul'jarra growls softly.>\n...تا Zul'jan.\nاز او محافظت می‌کنند انگار یکی از خودشان است. یکی از ارتششان.\nچه باشد چه نباشد، برای فهمیدن ماجرا باید آن‌ها را از میدان برداریم.", o = { "سه Fury را شکست بده" }, p = "تأیید کن\nباید با این‌ها حساب شود، $m.", c = "آن خنجر... آن قدرت...\nچه کار می‌کند؟\nباید حرفش را بفهمیم و برگردانیمش." }
WoWFQ[93024] = { t = "با من بیا", d = "همین‌جا بمان، hash'ura. من می‌روم داخل تا با او حرف بزنم.\nشاید بتوانم قانعش کنم خودش برود--و بگوید Malacrass چه نقشه‌ای دارد.\nبه خدا قسم امیدوارم عقلش بیاید.", o = { "با Zul'jarra صحبت کن", "حال Zul'jarra را بپرس" }, c = "Lor'themar نمی‌بیند؟ اگر Amani‌ها بیفتند، نوبت ماست که به سیل این هیولاها جواب بدهیم.\nبه کنار گذاشتن مقام hash'ura بودنمان، <name>، حاضرم دست روی دست بگذارم و بگذارم این اتفاق بیفتد." }
WoWFQ[93063] = { t = "نیزه‌های شکسته", o = { "12 سلاح باستانی از ارواح ترول‌ها در Altar of Wrath جمع کن." } }
WoWFQ[93064] = { t = "هیبتِ او", d = "باز هم همان کاهنه است--همانی که بقایایش را در سردابه پیدا کردیم.\nاین خاطرات--نه. خاطره نیستند. مثل کابوس‌اند. اتفاق هولناکی برای الهه افتاده. باید مستقیم ببینیمش. آوازش را از میان این‌همه غوغا بشنویم.\nمی‌ترسم این رؤیا به‌تنهایی از عهده‌ام برنیاید. هر دوتان به من بپیوندید و با هم ترسِ گذشتهٔ الهه را شاهد باشیم.", o = { "با Orweyna صحبت کن تا شاهد گذشته باشی" }, c = "Zandalariها ما را فرستادند تا بمیریم.\nدانستنش چیزی را عوض نمی‌کند. یا در برابر aqirها می‌ایستیم یا می‌افتیم." }
WoWFQ[93199] = { t = "خزیدن در گل‌ولای", d = "کودکان Ula'tek مرداب و ساکنانش را زیر و رو کردند. هر چه سر راهشان باشد می‌کشند، فقط برای این‌که تعدادشان بیشتر و قلمروشان بزرگ‌تر شود.\nهر کاری می‌توانی بکن تا تعدادشان را کم کنی. سرشان را گرم نگه دار. من قایم‌می‌شوم جلو می‌روم دنبال Wa'kani و بقیهٔ دیده‌بان‌ها می‌گردم.", o = { "Children of Ula'tek کشته‌شده" }, p = "پیدا شدی. وضعیت این‌جا از چیزی که فکر می‌کردم وخیم‌تر است. مارها بی‌رویه پخش می‌شوند و من هیچ‌وقت murlocها را این‌قدر معطل ندیده بودم.\nWa'kini را پیدا کردم. بقیه را تو جایی پیدا کردی؟", c = "خوب کار کردی و سرشان گرم بود تا من Wa'kani و بقیه را پیدا کنم.\nبه کودکان Ula'tek ضربه زدی، اما باید فشار را نگه داریم." }
WoWFQ[93229] = { t = "تخم‌مرغ سوخته", d = "مارها فقط دو چیز در سرشان است: کشتن و تولیدمثل. این بخش مرداب را اشغال کردند، هیچ چیز زنده‌ای در راهشان نگذاشتند و همه‌جا تخم گذاشتند!\nهر تخمی که سر راهت آمد بسوزان. ولی مواظب باش. اگر خیلی نزدیک شوی، می‌ترکند و نمی‌خواهی وقتی آن اتفاق افتاد جایی نزدیکشان باشی.", o = { "Wriggling Eggs سوزانده شد" }, p = "پیدا شدی. وضعیت این‌جا از چیزی که فکر می‌کردم وخیم‌تر است. مارها بی‌رویه پخش می‌شوند و من هیچ‌وقت murlocها را این‌قدر معطل ندیده بودم.\nWa'kini را پیدا کردم. بقیه را تو جایی پیدا کردی؟", c = "این باید کمی جلوی پیشرفتشان را بگیرد. دوست ندارم تصور کنم اگر قدمی از ما برنمی‌داشت چند تایشان تا آستانهٔ خانه‌مان می‌رسیدند.\nحالا فقط یک ورقهٔ بیکن و کمی نان تست مانده!" }
WoWFQ[93233] = { t = "وحشگری میان ویرانه‌ها", d = "murlocها در این ویرانه‌های قدیمی سنگر گرفته‌اند. معمولاً موجودهایی سرسخت ولی بزدل‌اند. این دسته فرق دارند. احتمالاً دیوانه شده‌اند--نمی‌دانم چرا، هم برایم مهم نیست.\nحین جست‌وجو ویرانه‌ها را پاک کن. اما بچه‌هایشان را نکش. به‌نظر نمی‌رسد در تأثیر آن چیزی که بقیه را دیوانه کرده باشند.", o = { "Murlocها کشته‌شده", "Curious Murpoleها رانده شدند" }, c = "آفرین! نمی‌خواهیم دو دشمن پشت سرمان داشته باشیم. امیدوارم بچه‌ها به‌اندازهٔ کافی دور شده باشند که مثل بزرگ‌ترهایشان گمراه نشوند." }
WoWFQ[93239] = { t = "دیده‌بان‌ها در مرداب", d = "وقتی تو دنبال نجات Wa'kani بودی، کمی بیشتر گشتم. فکر می‌کنم بقیهٔ دیده‌بان‌ها را murlocها برده‌اند.\nباید ژرف‌تر در ویرانه‌ها بگردیم. من دور می‌زنم و می‌بینم چیزی پیدا می‌کنم یا نه. تو در جنگیدن از من بهتری، پس می‌توانی جاهایی را بگردی که من نمی‌توانم. دیده‌بان‌ها را پیدا کن و نزدیک اسکله به من ملحق شو.", o = { "Ndamu پیدا شد", "Abaano پیدا شد", "Tefokal پیدا شد" }, p = "قرار بود این فقط یک مأموریت دیده‌بانی باشد...\nدیده‌بان‌ها را پیدا کردی؟", c = "برای Ndamu عزا خواهیم گرفت. تا آخرین لحظه از Wa'kani محافظت کرد، همان‌طور که وظیفه‌اش بود. خوشحالم که تو و بقیه سالم برگشتید." }
WoWFQ[93339] = { t = "خر و فروش تزئینات", d = "تا حالا murlocها را این‌قدر خونخوار ندیده بودم. چند تایشان چیزی پَردار سبزرنگ براق دارند. شاید همان منبع تاریکی‌ای باشد که حس می‌کنم.\nوقتی میان ویرانه‌ها هستی، حواست به این اشیا باشد. فکر می‌کنم murlocها چیزی از زیر خاک بیرون کشیده‌اند که عقلشان را برداشته.", o = { "Feathered Trinket" }, p = "می‌دانم Zawadi فکر می‌کند حضور من این‌جا هدر دادن وقت است، حتی با این‌که Ophidia را انداختیم. اگر ثابت کنم murlocها به چیز شومی دست پیدا کرده‌اند، ناچار است قبول کند حق با من بود که بیایم.\nاین ویرانه‌ها باستانی‌اند. چه می‌شود گفت چه چیزهایی در گل فرو رفته و حالا دست‌های حریصشان بیرونشان کشیده.", c = "جالب است. به‌نظر می‌رسد نشان‌های ساختهٔ همان موجودات ماری‌اند. می‌شود منبع جنون باشند؟\n<Wa'kani cups one of the trinkets in her hands, concentrating. After a few moments, she sighs.>\nهیچ. جادوی باقی‌مانده‌ای حس نمی‌کنم. این تزئینات عامل نیستند. همان‌طور که حدس می‌زدم." }
WoWFQ[93340] = { t = "پارهٔ سایه", d = "فکر می‌کردم murlocها را تزئینات دیوانه کرده، اما فقط اسباب‌بازی‌هایی هستند که مارها ساخته‌اند. وقتی به آن فانوس دریایی نزدیک‌تر شدیم، شروع به شک کردن کردم که عامل همین‌ها نباشند.\nاز همین‌جا حسش می‌کنم. تاریکی‌ای تپنده. باستانی. اگر آن بالا بروی، شاید منبع اصلی جنون murlocها را پیدا کنی.", o = { "Smrglemrgl کشته‌شده", "The Shadow Shard نابود شد" }, p = "وقتی که صرف جمع کردن تزئینات کردی هدر نرفت. وقتی آن‌ها را رد کردیم، توانستیم منبع را محدودتر کنیم!\nاز آن گذشته، من هرگز چنین موج‌هایی از تاریکی را که از آن برج می‌آید حس نکرده بودم. هر چه هست که murlocها را کنترل می‌کند پیدا کن و نابودش کن.", c = "یعنی رئیس murlocها کریستالی پر از سایه داشت؟ عجیب است...\nممکن است murlocها این یادگار باستانی را از زیر خاک بیرون کشیده باشند و قدرتش بلعیده باشدشان. حیف که نابودش کردی. دوست داشتم مطالعه‌اش کنم.\nاز دست دادن Ndamu ضربهٔ بزرگی است، اما کاری که امروز کردی باعث شد قربانی‌اش بیهوده نباشد. به مارها ضربهٔ سختی زدیم، murlocها کم‌کم آرام می‌گیرند و منبع انرژی تاریک را هم نابود کردیم. ممنونم، <name>." }
WoWFQ[93387] = { t = "سر و کله زدن با مزاحم‌ها", d = "هر بار از کلبه‌ام بیرون می‌روم، برگردم می‌بینم یک به‌هم‌ریختگی و ردپای خیس murlocهای ریز و درشت.\nبرای جلوی این مزاحمان دوزیستی نقشهٔ تازه‌ای دارم، اما باید چند ماده اولیه جور کنم.\nتا من لیستم را درست می‌کنم--روحی به اسم Jelvik هست که مدام دنبالم می‌کند. بگو پیاده شود و برود.", o = { "Jelvik رویارویی شد" }, p = "یعنی چی بگویم نمی‌بینی‌اش؟", c = "تا این لحظه دارد برایمان بازی می‌شود.\nمی‌دانم آن‌جاست. او هم می‌داند که می‌دانم آن‌جاست، ولی اگر وانمود کنم نمی‌بینمش، این دور را من برده‌ام!\nالبته بد نمی‌شود اگر کمکش کنی. آن‌وقت هر دو می‌بریم. فقط به او نگو گفتم." }
WoWFQ[93388] = { t = "کیمیاگری نامتعارف", d = "لیستم آماده است. باید مواد را جمع کنی تا برای همیشه این murlocها را دور نگه داریم.\nاول با Maka de Trawler حرف بزن. او و بافندهٔ جلبک Torga's Beak توی خلیج ماهی می‌گیرند. چند شکم ماهی برایم بیاور--زننده و بی‌نقص.\nبعد برو به Mlurkkr Mire. آن مروارید کثیف قدیمی را می‌خواهم که فکر می‌کنند این‌قدر باارزش است.\nهمان حوالی، از چند تا از این مارمردمانِ اعصاب‌خردکن چند فلس بگیر.\nبگویم که فقط از انواع خوبش می‌خواهم.", o = { "با Maka the Trawler صحبت کن", "Pile of Fish Guts", "Tarnished Pearl", "Undamaged Serpent Scale" }, p = "کالاها را آوردی؟", c = "موجودی مفیدی هستی!\nمن هم روح‌هایی دارم که آزارم می‌دهند هم murlocهایی که هر بار از کلبه بیرون می‌روم به‌هم‌ریختگی راه می‌اندازند. اگر مزاحم نبودند که دیگر مزاحم نبودند، این‌طور نیست؟\nمی‌فهمم--تو همان کسی خواهی بود که مشکل مرا حل می‌کند." }
WoWFQ[93389] = { t = "خون‌صخره", d = "ان‌قدر این‌جام که تکه‌هایی از حافظه‌ام در گذر زمان گم شده. جای چیزی که دوستش داشتم خالی‌ست.\nتا نفهمم چه کسی یا چه چیزی بود، آرام نمی‌گیرم. فقط یک کلمه یادم مانده... Rocksblood. نمی‌دانم چه کسی یا چه چیزی است.\nویرانه‌های murlocها در جنوب را بگرد. کسی آن‌جاست که می‌تواند راهت را نشان بدهد.\nحالا که Ofi لجبازی می‌کند، باید تو کمکم کنی یادم بیاید.", o = { "پیدا شدن کسی که می‌داند", "تکهٔ گم‌شده پیدا شد", "شیء گم‌شده پیدا شد", "Scroll of Seeking" }, c = "تکه‌ها دارد سر هم می‌شود... تقریباً یادم آمد. برگرد پیش Ofi. باید کمی فکر کنم.\nامید دوباره به دلم برگشت، <class>. تو این کار را کردی و من ازت ممنونم." }
WoWFQ[93390] = { t = "شاگردِ قابل قبول", d = "این بخشش تند و بند دارد.\nمخلوط را آماده کردم. همین الان هم ناخوشایند است، اما حالا می‌رویم واقعاً زننده‌اش کنیم.\nوقتی از نظر روانی آماده شدی که یک مفیدِ سودمند باشی، خبرم کن.", o = { "با Ofi صحبت کن", "درست کردن Pungent Concoction" }, p = "حس می‌کنی به چالش کشیده شدی؟", c = "Oosha! حسابی تند و داغ است. این‌قدر قوی بودت را نمی‌دانستم.\nحداقل این بار منفجر نشد.\nبد نیست، <race>." }
WoWFQ[93391] = { t = "بو بده بهش", d = "بهتر است بازدارنده‌های کوچکمان را ببری به آن نوار خشکی میان خانهٔ من و باتلاق دیوانه‌ها.\nشاید بخواهند جلویت را بگیرند، اما محکم بایست. اگر جواب بدهد، دم را روی دم می‌گذارند و فرار می‌کنند.\nراستی murlocها اصلاً دم دارند؟", o = { "بازدارندهٔ اول murloc گذاشته شد", "بازدارندهٔ دوم murloc گذاشته شد", "بازدارندهٔ سوم murloc گذاشته شد", "Murloc Deterrent" }, p = "murlocها رفتند؟", c = "آها! آفرین. مدتی است که این باید فراری‌شان نگه دارد.\nمن عاشق بوی آشفتگی در صبح‌گاهم.\nالبته شاید هم بو از تو باشد. می‌شود کمی عقب‌تر وایستی؟" }
WoWFQ[93392] = { t = "بازیابی خاطره‌ها", d = "شمال‌شرق، یک جزیرهٔ کوچک هست. یادم می‌آید سال‌ها پیش غرش و زوزه‌ای بزرگ روی آب‌ها طنین‌انداز بود.\nخشم را می‌شنیدم، اما درد هم بود. جرئت نمی‌کردم به آن مکان نزدیک شوم. چه می‌شود اگر گم می‌شدم و احساس‌های خودم بلعیده می‌شد توی احساس‌های بزرگ‌ترش؟\nیک روز دوباره ساکت شد، اما حالا حس می‌کنم این آخرین کلید قفلی است که روی روحم خورده.\nبرو آن‌جا. تکهٔ آخر را پیدا کن.", o = { "جانور تنها شکست‌خورده", "Rocksblood پیدا شد" }, p = "پیدایش کردی؟", c = "شاید از خوشحالی اشک بریزم که روحم را پر کرده. فکر می‌کرد سال‌ها پیش رفته و حتی خودش هم از ذهنم رفته.\nحالا Sava عزیزم برای همیشه با من خواهد بود.\nممنونم، <name>." }
WoWFQ[93393] = { t = "کمی مهربانی", d = "می‌دانی رفیق، هر چقدر هم خوشحالم... دائم به آن جانور فکر می‌کنم که چقدر غمگینش کردیم. آرزو نمی‌کنم چنین حسی سراغ موجود زندهٔ دیگری برود.\nاو سال‌های گم‌شدن Sava عزیز را از او مراقبت کرد. می‌شود آخرین خواسته‌اش را برآورده کنیم؟\nاگر برای خودش یاری‌ای بفرستی، بدهیمان را پس می‌دهد.\nبعد می‌توانیم برای همیشه برویم--من و Sava آزاد می‌شویم.", o = { "با Ofi the Sly صحبت کن", "تخم پاک‌شده گذاشته شد", "یار رسانده شد" }, p = "به هیچ‌کس نگو که من هم در این ماجرا سهم داشتم.\nاگر مردم فکر کنند نرم شده‌ام، دیگر رهایم نمی‌کنند.", c = "حالا بازی‌مان تمام شد. حدس می‌زنم با رفتن رفیقم این حوالی آرام‌تر شود.\nچه؟ من همیشه وانمود می‌کنم رفقایم وجود ندارند. تو کی هستی؟ آها!\nآه، به‌نظر می‌رسد یکی از کوچولوها همدمی تو را به همدمی آن جانور ترجیح داد. بهتر است با خودت ببری‌اش." }
WoWFQ[93417] = { t = "خزانه‌های Atal'Utek: محراب نیش‌ها", d = "Orweyna آن‌چه دید را برایمان گفت...\nبه این Zul'jan لعنت! واقعاً نمی‌فهمد چه کرده؟ با همهٔ موفقیت‌هایی که داشتیم، او پیوندهایی که Zul'jarra میان ما دو نفر بافته را ضعف می‌بیند و هنوز دنبال همان خیال «امپراتوری برتر Amani» است.\nو در این راه، خواهرش را به‌شدت زخمی کرده.\nاما شاید Zul'jarra حق دارد--شاید واقعاً خبر ندارد.\nباید آن خنجر را به دست بیاوریم. یا با عقل سرش، یا به زور.", o = { "از Gate of the Eastern Fang وارد Vaults of Atal'Utek شو", "حال سربازانی که از Vaults of Atal'Utek محافظت می‌کنند را بپرس", "داخل Vaults of Atal'Utek با Lady Liadrin دیدار کن", "با Liadrin صحبت کن تا ورود به follower dungeon آغاز شود", "پاک‌سازی Altar of Fangs و روبه‌رو شدن با Zul'jan", "در Altar of Fangs با Lady Liadrin صحبت کن", "خروج از Vaults of Atal'Utek" }, c = "از وقتی خنجر را برداشتیم، از درونم لرز سردی می‌آید.\nبیایید سریع بهش نگاهی بیندازیم." }
WoWFQ[93418] = { t = "ژرفای زهرآگین", d = "در غبار زهر چیزهایی دیدم.\nصدای جیغ Zul'jan را شنیدم، حس کردم چه چیزی دارد از درونش را می‌خورد.\nصدای زمزمهٔ Malacrass در گوشش را شنیدم.\nUla'tek از همان اول آفت جان Amani‌ها بوده. به چه سران‌وپایانی رفتیم برای قدرت و امپراتوری، و چه خونی دادیم...\nآن عظمت نبود. در اعماق قلبش، Zul'jan هم همین را می‌داند.\nMalacrass پدربزرگم را از من گرفت. نمی‌گذارم Zul'jan را هم ببرد.", o = { "به Gate of the Serpent's Eye سفر کن", "رید Venomous Abyss را در هر درجهٔ سختی کامل کن", "برای ورود به رید در حالت داستانی با Seh'ka the Sturdy صحبت کن" }, c = "Zul'jarra خودش را مقصر می‌داند، اما ما می‌دانیم که او هر کاری--هر کاری--کرد تا نجاتش بدهد." }
WoWFQ[93419] = { t = "ماهیت زخم‌هایش", d = "Fang از زمان احضار Ula'tek نفرین شده. می‌توانیم از آن برای درمان Zul'jarra استفاده کنیم. فقط--\nباید سریع باشیم. دارد از بین می‌رود!", o = { "Fang of Ula'tek گذاشته شد", "Fang of Ula'tek نابود شد" }, c = "<Name>... ممنونم. چیزهای زیادی دیدم.\n<Zul'jarra gets a far-off look and growls.>\nدیگر دیر است... نه!\n<Zul'jarra shudders violently and scowls, shaking off the vision.>\nباید برادرم را پیدا کنیم." }
WoWFQ[93449] = { t = "دردسر در مرداب", d = "گروهی از قومم به Mlurkkr Mire رفتند و برنگشتند. داشتند حملهٔ کودکان Ula'tek در آن منطقه را بررسی می‌کردند. خبرهای نگران‌کننده‌ای هم هست که murlocهای محل رفتار خشن‌تر از همیشگی دارند، و کاهنهٔ Wa'kani گفته انرژی تاریک قوی‌ای حس کرده که می‌خواست بررسی‌اش کند.\nرهبرشان، Zawadi، یک ساعت پیش باید خبر می‌آورد. می‌روی پیدایشان کنی و اگر لازم شد کمکشان می‌کنی؟", p = "Zawadi گروهی از دیده‌بان‌هایش را برد تا وضعیت Mlurkkr Mire را ببیند. خواهرش، Wa'kani، بعد از حس کردن قدرتی تاریک که از مرداب می‌آمد، اصرار کرد همراهشان برود.\nنگرانم گیر افتاده باشند.", c = "Ra'kamu فرستاده؟ خوب است. کمکم می‌آوری." }
WoWFQ[93454] = { t = "حرف‌هایی که باید شنید", d = "Malacrass پدربزرگم را در رساندن Amani‌ها به نابودی یاری کرد. حالا می‌خواهد همین کار را با برادرم بکند. اگر می‌شد این دو را از هم جدا کرد...\nاما Jan حرف نمی‌زند.\nفکر می‌کند Ula'tek سلاحی است که امپراتوری Amani را برمی‌گرداند. بعد از آن رؤیایی که دید و خدا می‌داند Malacrass چه‌ها به او گفت، نمی‌توانم فکرش را عوض کنم.\nhash'ey مشورت می‌خواهد، hash'urای من. بقیه را جمع کن و به من بپیوند.", o = { "متحدان جمع شدند", "سخنان Lady Liadrin شنیده شد", "سخنان Captain Tokka شنیده شد", "سخنان Orweyna شنیده شد", "سخنان Tak'lejo شنیده شد", "Zul'jarra مشورت شد", "دربارهٔ Zul'jan پند داده شد" }, c = "رؤیاهای haranirها هنوز هیچ‌وقت این‌قدر درد این‌قدر ایجاد نکرده بودند...\nاما دانش در دست اشتباه می‌تواند هم برای خوبی به کار رود هم برای بدی." }
WoWFQ[93576] = { t = "جست‌وجوی Wa'kani", d = "وقتی تو سر مارها گرم بودی، من دنبال Wa'kani و بقیهٔ دیده‌بان‌ها می‌گشتم. دیده‌بان‌ها هنوز گم‌اند، اما Wa'kani در همان معبد است.\nسعی کردم نزدیک شوم، اما حسابی نگهبانی دارد. البته برای تو باید بازی باشد. لطفاً پیش از آن‌که مارها کاری زشت با خواهر احمقم بکنند، نجاتش بده.", o = { "Wa'kani پیدا شد" }, p = "پیدا شدی. وضعیت این‌جا از چیزی که فکر می‌کردم وخیم‌تر است. مارها بی‌رویه پخش می‌شوند و من هیچ‌وقت murlocها را این‌قدر معطل ندیده بودم.\nWa'kini را پیدا کردم. بقیه را تو جایی پیدا کردی؟", c = "ممنون که آزادم کردی. هنوز نمی‌توانیم برویم. منبع تمام این تخم‌ها را پیدا کرده‌ام!" }
WoWFQ[93648] = { t = "دزدیِ گِردالود", d = "gnarldinهای همین حوالی آذوقهٔ فراوانی دارند که به کار اردوگاه می‌آید. باید راحت دزدی شود.", o = { "Gnarldin Supplies" }, c = "باور نمی‌کنی اردوگاهمان با چه نرخی آذوقه مصرف می‌کند. ممنون!" }
WoWFQ[93649] = { t = "شجاعتِ سنگ", d = "شمن‌هایمان برای درمان تب به سنگ کیسه صفرا نیاز دارند. گوسفندهای حوالی باید پر از آن باشند.", o = { "Lumpy Gallstone", "Venom-Corroded Gallstone" }, c = "سربازها به‌زودی حالشان خوب می‌شود!" }
WoWFQ[93664] = { t = "ماهی گندیده", d = "murlocها دارد سربازهایمان را آزار می‌دهند. جای خودشان نشانشان بده.", o = { "Venom-Crazed Murkfen کشته‌شده" }, c = "دو بار فکر کن قبل از این‌که دست به Amani‌ها بزنی. ممنون، hash'ura." }
WoWFQ[93669] = { t = "نفرین حریصی", d = "ارواح به دنیای ما چسبیده‌اند چون نمی‌توانند از گنج‌های باستانی‌شان بگذرند. رنجشان را کم کن.", o = { "Cursed Zandalari Coin" }, c = "سرزمین دارد آرام می‌گیرد... و جیب تو کمی سنگین‌تر می‌شود." }
WoWFQ[93670] = { t = "حالا سیب‌ها چطور؟", d = "باید غذا جمع کنیم. ببین murlocها چه می‌چینند.", o = { "Swamp Apple" }, c = "طعمشان چندان خوب نیست... اما سربازها خوشحال می‌شوند که میوهٔ تازه داشته باشند." }
WoWFQ[93671] = { t = "فشارِ تنگ", d = "برای داروهایمان به زهر قورباغه نیاز داریم. بگیرش از دلشان بیرون!", o = { "Freshly-Squeezed Frog Poison" }, c = "آه، هیچ چیز مثل قورباغهٔ تازه‌فشرده نمی‌شود." }
WoWFQ[93672] = { t = "استراحتِ تیغ", d = "آهنگرهای امپراتوری قدیم با سلاح‌هایشان به خاک سپرده شده‌اند. روح‌هایشان را آزاد کن.", o = { "Smith Spirits جن‌گیری شد" }, c = "ارواح آرام گرفتند. حواسم هست سلاح‌هایشان بیهوده نماند." }
WoWFQ[93841] = { t = "اشباح حلقه", d = "چند وقت پیش در Ring of Glory بودم. تو که بودی؟ آن‌جا پر از روح است و یکی از آن‌ها حسابی ترساند! همان جلو آمد و خواست با من حرف بزند! آن‌قدر اعصابم ناخنک شده بود که نماندم ببینم چه می‌خواهد.\nتو خوش‌تیپ و قوی به نظر می‌رسی. شاید بهتر باشد تو بروی حالش را بگیری.", c = "کی؟ آه، حالا کاهنه را یادم آمد. وقتی خواستم با او حرف بزنم آن‌قدر بلند جیغ زد که هیچ. مدت‌ها بود این‌قدر نخندیده بودم.\nاومدی کمک؟" }
WoWFQ[93842] = { t = "شکفتن و پژمردن", d = "وقتم کم است و باید ببینم می‌توانم محبوبم، Eshaye، را نجات بدهم. در حلقه گیر افتاده و می‌خواهم پیش از آن‌که کاملاً محو شوم، از این چرخه نجاتش بدهم.\nقبلاً با دسته‌های گل شکوفهٔ sweetsaw می‌توانسم بهش برسم. اما دیگر نمی‌توانم بگیرمشان. برایم جمع می‌کنی؟", o = { "Sweetsaw Bloom جمع شد" }, p = "فکر می‌کنم عطر شکوفه‌ها همیشه برش می‌گرداند. من دیگر هیچ بویی حس نمی‌کنم. اگر او هم نمی‌تواند، شاید هیچ چیز برگرداندنش نکند.", c = "زیبا نیستند؟\n<He leans close, inhaling, but then sighs disappointedly.>\nنمی‌توانم بو کنمشان. کاش یک بار دیگر می‌شد. امیدوارم Eshaye هنوز بتواند." }
WoWFQ[93843] = { t = "استخراج‌های اکتوپلاسمی", d = "بالای Ring of Glory، روح‌هایی مثل من هستند که تاجرند. انواع و اقسام چیزها را به روح‌های دیگر می‌فروشند، اما من قبلاً با نوشیدنی‌ای از Mab'jul توجه Eshaye را جلب کردم.\nکالاهای بازار را با اکتوپلاسم می‌خرند که از ارواح از‌هم‌پاشیده و زنبورهای اطراف حلقه جمع می‌شود. مخصوصاً از فرقه‌گراها، که از بقیه می‌دزدند.", o = { "Ectoplasm" }, p = "اول‌ها فقط در مرداب سرگردان بودیم: سردرگم، خشمگین، زخمی، ترسان. بعد از هزاران سال، بعضی‌ها یاد گرفتند اکتوپلاسمی را که از از‌هم‌گسیختگی روح دیگری جا می‌ماند تبدیل کنند. این پول کم‌کم چندان جست‌وجو شد که هیچ.\nاینجا روح را نمی‌شود برای همیشه نابود کرد. بالاخره بازسازی می‌شود، اما خیلی طول می‌کشد. چون هیچ‌کداممان نمی‌توانیم برویم، همیشه اکتوپلاسم هست، هرچند جمع کردنش سخت است. توانستی به‌اندازهٔ کافی تهیه کنی؟", c = "خوب کار کردی. یک قدم به آزاد کردن Eshaye از حلقه نزدیک‌تر شدیم." }
WoWFQ[93849] = { t = "فروشگاه اکتوپلاسمی", d = "Eshaye حتماً این گل‌ها را دوست می‌دارد! حالا فقط نوشیدنی شبح‌مانند مانده. اکتوپلاسم را ببر پیش Mab'jul و با یک بطری نوشیدنی شبح‌مانند عوضش کن.\nنوعی شراب که از اکتوپلاسم برداشت‌شده ساخته می‌شود و حسابی گواراست. گاهی می‌تواند جلوی از‌هم‌پاشیدن را بگیرد.", o = { "Spectral Brew", "هدیه‌ها به Eshaye داده شد", "دستهٔ گل شکوفه" }, p = "یادم می‌آید اولین باری که بهش گل دادم. فکر نمی‌کرد جنگجویی مثل او سرخ شود، اما شد. امیدوارم لبخند آن روز را هرگز فراموش نکنم.", c = "فهمیدم. از آخرین باری که بهش گل دادم خیلی گذشته. شاید خاطرهٔ گل‌ها و روزهای با همی‌مان مدت‌هاست رفته باشد." }
WoWFQ[93851] = { t = "هم‌آوایی با اشباح", d = "شانس‌مان زیاد نبود، اما می‌خواستم امتحانش کنم.\n<He pauses a moment and shudders, seeming to flicker at the edges.>\nاز فکرم چیزی باقی نمانده، <name>. می‌روی می‌گردی؟ بعضی از همین‌ها شاید راهی برای رسیدن به Eshaye بدانند. من آن‌قدر بهشان نزدیک خوش‌آمد نیستم، وگرنه خودم می‌آمدم.", o = { "Mab'jul بازجویی شد", "Ata'leki بازجویی شد", "Je'lana بازجویی شد", "Kir'bo بازجویی شد" }, p = "امیدوارم یکی از آن‌ها راه‌حلی داشته باشد. وقت من کم است.", c = "چالش با Eshaye؟ البته که! چرا به خودم نرسید؟\nیعنی، احتمالاً چون نمی‌توانم ببرمش." }
WoWFQ[93906] = { t = "رهاسازیِ آن دو", d = "حتی به ذهنم نرسیده بود به Eshaye حمله کنم. وقت تلف می‌کردم که کاری کنم با من حرف بزند، بی‌این‌که بدانم چطور باید با او حرف زد.\nبرایم انجامش می‌دهی؟ Eshaye را به چالش بکش و ببرش. شاید این بیدارش کند؟ حس می‌کنم امیدی دارد جوانه می‌زند.", o = { "Eshaye شکست‌خورده" }, c = "ممنون که از آن چرخه بیدارم کردی، <name>. همه‌چیزی که یادم بود جست‌وجوی پیروزی در روزی بود که کشته شدیم. یادم نبود برای چه می‌جنگیدم: برگشتن به Ja'bonu و زندگی‌ای که داشتیم.\nبرای اولین بار در هزاران سال حس می‌کنم کامل‌ام. هر چه بود که ما را این‌جا گرفت، دیگر نمی‌تواند من و Ja'bonu را نگه دارد. حالا می‌توانیم برویم، به سوی ماجرای بعدی، با هم." }
WoWFQ[94031] = { t = "استخوان‌های روحم", d = "وقت داری که یک نفرین را بشکنی، <class>؟\nمن باقی‌ماندهٔ یک گویندهٔ loa برای Gral هستم. اسیران را در Gral's Belly مهار می‌کردم. اما کشتی‌مان غرق شد، من مُردم و اسیران فرار کردند.\nقدرت‌هایم دیگر روی زنده‌ها کار نمی‌کرد. اما روی کاپیتان کار کرد، که با من مُرد.\nاز خشمش بر شکستم وحشت‌زده بودم و آیینی راه انداختم تا با استخوان‌های خودم در کشتی حبسش کنم.\nبعد از این‌همه سال روحم به استخوان‌ها نشسته و حالا نمی‌توانم تکانشان بدهم. می‌شود استخوان‌هایم را برایم بیاوری؟", o = { "Yl'mul's Skull", "Yl'mul's Other Arm", "Yl'mul's Ribcage" }, p = "این آیین، آیین عجیبی بود که معلمم خیلی، خیلی وقت پیش یادم داد.\nهرگز فکر نمی‌کردم روزی در قامت روح به آیین‌ها نیاز پیدا کنم، اما تصور خشم کاپیتان را هم نمی‌توانستم بکنم.", c = "قدرت Gral، روحم... همه‌اش دوباره همین‌جاست. ممنون که استخوان‌هایم را برگرداندی، <name>." }
WoWFQ[94035] = { t = "گوشت برای استخوان‌ها", d = "برای این‌که روحم را از استخوان‌ها به این‌جا بیاورم، باید آیینی انجام بدهم.\nGral loa خیلی چیزهاست، اما بیشترِ بیشتر دریاست. یک کوسه است. و عاشق گوشت است!\nاز موجودات دریایی این حوالی گوشت بیاور. انجام آیین با چیزی سرخ و چکه‌چکه که زمینم را بگیرد، راحت‌تر می‌شود.", o = { "Gillfish خورده شد", "Sea Creature Meat" }, p = "بسیاری از گویندگان loa برای Gral در آیین‌هایشان از گوشت استفاده می‌کنند. بیرون کشیدن روحم از استخوان‌ها گوشت زیادی می‌برد. اما برای تو چیزی نیست، این‌طور نیست <class>؟", c = "عالی، عالی! این‌همه گوشت برای این استخوان‌های پیر کافی است." }
WoWFQ[94036] = { t = "آخرین اسیر", d = "نمی‌توانم وانمود کنم از کاپیتان بهترم.\nهر دومان لذت می‌بردیم از بالانشستن بر اسیران. وقتی او عصبانیتش را سرشان خالی می‌کرد، جلویش را نمی‌گرفتم.\nاما در این مدت که با هم این‌جا گرفتاریم، فکر کردم. لحظه‌ای که برایش مفید نبودم، عصبانی شد. و حالا می‌خواهم این ماجرا تمام شود.\nنمی‌توانم دیگر ناظم بی‌تفاوتی او باشم. می‌شود آرامش بدهی‌اش؟", o = { "Captain Sal'chatah کشته‌شده" }, p = "Captain Sal'chatah هیچ‌وقت این را نخواست که من از او قدرتمندتر باشم. همیشه راهی برای ضربه زدن به من پیدا می‌کرد.\nحبس کردنش این‌جا اول‌ها خوب بود، اما حالا حس می‌کنم این زحمت از من در رفته.\nاما در این مدت که با هم این‌جا گرفتاریم، فکر کردم. لحظه‌ای که برایش مفید نبودم، عصبانی شد. و حالا می‌خواهم این ماجرا تمام شود.", c = "یکی از دو روحی که این نفرین را زنده نگه داشته بود را جن‌گرفتی. ازت ممنونم." }
WoWFQ[94040] = { t = "گوشت و استخوان و روح", d = "همه‌چیز برای آیین آماده است.\nمرا در Tooth o' Sargoth ملاقات کن. کمکم می‌کنی روحم سالم سر جایش برگردد و بعد این نفرین برای همیشه تمام می‌شود.\nباد Gral در آن‌سو در مورد کوتاهی‌هایم داوری کند.", o = { "Loa Speaker Yl'mul در Tooth of Sargoth پیدا شد", "Yl'mul's Skull پرتاب شد", "Yl'mul's Other Arm پرتاب شد", "Yl'mul's Ribcage پرتاب شد", "گوشت پرتاب شد" }, p = "فقط چند قدم مانده. باید استخوان‌ها پرتاب شوند و آب آشفته شود تا روحم دوباره یک تکه شود.", c = "قدرت Gral، روحم... همه‌اش دوباره همین‌جاست. ممنون که استخوان‌هایم را برگرداندی، <name>." }
WoWFQ[94447] = { t = "Ophidia مادرزاد", d = "Zawadi سالم است، نه؟ خوب است. نباید چیزی سرش بیاید. باید با این کرم‌های عظیم‌الجثه حساب کنیم.\nهمان‌جا، کنار ساحل، یکی از مادرزادهایشان است. موجودی پست! عامل تمام تخم‌هایی که این حوالی می‌بینی. بکشش. تهاجمشان می‌خوابد و قومم وقت بیشتری برای سازمان‌دادن به حمله پیدا می‌کند.\nباید به زخم‌هایم برسم. قایم می‌شوم و منتظرت می‌مانم.", o = { "Ophidia کشته‌شده", "برگرد پیش Wa'kani" }, c = "شاید Wa'kani این مأموریت را خراب کرد، اما درست بود که تو را فرستاد مادرتخم را بیندازد. ضربهٔ بزرگی به نقشه‌های توسعهٔ کودکان Ula'tek در این باتلاق بود.\nبا این حال، Ndamu و بقیهٔ دیده‌بان‌ها هنوز گم‌اند. می‌ترسم murlocها آن‌ها را داشته باشند." }
WoWFQ[94571] = { t = "خاکستر تاریخ", d = "کاهنه‌های قدیم مردگانشان را می‌سوزاندند. استخوان‌هایی که جا می‌گذاشتند قدرتی داشتند... قدرتی که ما هم می‌توانیم به کار ببریم.", o = { "Ritually-Charred Bones" }, c = "این استخوان‌ها به کاهنه‌هایمان قدرت می‌دهند. ممنون." }
WoWFQ[94572] = { t = "پوستهٔ آینده", d = "آینده در کمین است... پوستهٔ لاک‌پشت برایم پیدا کن تا در ترک‌هایش سرنوشت‌مان را بخوانم!", o = { "Turtle Shells خوانده شد" }, c = "آزمون‌های بزرگی در پیش داریم. بهتر است آماده باشیم." }
WoWFQ[94573] = { t = "کفِ پر از لارو", d = "این پشه‌های وحشتناک مرداب دارد دیده‌بان‌هایمان را بیمار می‌کند. لهشان کن!", o = { "Burrowing Gnat Larvae کشته‌شده" }, c = "مرداب حالا خیلی آرام‌تر است. ممنون." }
WoWFQ[94574] = { t = "دزد تخم", d = "با شکم خالی نمی‌شود با مارها جنگید! در آن پرتگاه‌ها دنبال لانه‌های پرنده بگرد تا پروتئین پیدا کنیم.", o = { "Speckled Seabird Egg" }, c = "این بهتر است! صبحانهٔ مفصب سرباز قوی می‌سازد." }
WoWFQ[94611] = { t = "شکارچیان و شکارها", d = "ما تنها قربانیان کودکان Ula'tek نیستیم. حیات وحش به کمک ما نیاز دارد.", o = { "Ravenous Predators کشته‌شده", "حیات وحش به هوش آمد" }, c = "حیوانات راحت‌تر نفس می‌کشند. ما هم." }
WoWFQ[94612] = { t = "چنگ برای جشن", d = "یک دیده‌بان خرچنگ‌هایی در سواحل دید! حدس می‌زنم کمی گوشت خرچنگ تازه سربازها را سرحال بیاورد.", o = { "Morsel of Crab Meat", "Big Meaty Claw" }, c = "بشقاب خرچنگ، درست مثل دست‌پخت مادربزرگ! همه را سرحال می‌آورد." }
WoWFQ[94796] = { t = "درمان مقاومتِ نفرین", d = "حالا که انبارکننده رفته، جمعیت ماهی‌ها چند برابر شده. سیل ماهی‌هایی بدون هیچ نفرینی!\nCaptain Tokka می‌خواهد این ماهی‌های مقاوم به نفرین را مطالعه کند. برو چند تا از کبدشان را جمع کن تا ببینیم چه چیزی آن‌ها را در آب نگه می‌دارد.\nاگر بخواهیم نفرینِ زهر را برای خودمان به کار بگیریم، به ماهی نفرینی بیشتری نیاز داریم!", o = { "Whole Uncursed Liver" }, p = "Captain Tokka همیشه با چیزی سر و کله دارد. قفسه‌های پر از امعاء و احشاء ماهی‌های نفرینی دارد. ح-حتماً هر چه پیدا کنی را می‌پسندد، <name>!", c = "<Second Mate Sluggs stares at the fish livers with wide eyes.>\nا-اوه، ممنون، <name>! Captain Tokka... خیلی خوشش می‌آید.\n<She gulps.>\nمی‌توانی همان‌جا بگذاری‌شان. ممنون. واقعاً." }
WoWFQ[94798] = { t = "آرزوی Ssak'mozek", d = "Captain Tokka طعمه را برای Ssak'mozek آماده کرد. وقت کشتن هیولاست!\nطعمه را به داخل مرداب ببر، نزدیک کشتی شکستهٔ Pa'ku's Talon. خودت را آماده کن، بعد روی سنگ‌ها بگذارش.\nSsak'mozek کشیده می‌شود سمت طعمه. بکشش.", o = { "Hydra Lure گذاشته شد", "Ssak'mozek کشته‌شده" }, p = "معمولاً از هیدراها می‌شنویم که مدام سرشان درست می‌شود. Ssak'mozek چیزی بدتر است، ساختهٔ کودکان Ula'tek و تغییرشکل‌یافته با نفرین زهر.\nوقتی به‌روش رویارو شدی حواست باشد، <name>.", c = "<Second Mate Sluggs shakes with excitement.>\nطعمه کار کرد! درست همان‌طور که Captain Tokka یادم داد. و همه‌اش به لطف تو.\nکارهای دیگری هم مانده، <name>، اما کمی جشن پیروزی‌ات را بگیر. تا فردا!" }
WoWFQ[94800] = { t = "خرچنگ‌های خردشده", d = "Hegvosh انبارکننده برگشته!\nهر چه سر راهش باشد را کشتن را شروع کرده. این بار، در جنوب، همهٔ تله‌های خرچنگ‌مان را لگدمال کرد.\nهر تکهٔ سالم از تله‌ها که پیدا کردی نجات بده. باید دوباره بسازیمشان.", o = { "Crab Trap Pieces جمع شد" }, p = "ما خرچنگ برای غذا تله می‌گذاریم، بیشتر. حتی Captain Tokka هم باید غذا بخورد! دوست دارد روش‌های تازه و، خب، جالبی برای تله‌گذاری خرچنگ بسازد. بیشتر با سوزن‌های نفرین‌زهر.", c = "می‌برم‌شان پیش Captain Tokka تا تله‌ها را دوباره سرهم کنیم.\nانبارکننده از چند راه آذوقه‌مان را کم می‌کند، اما هیچ‌وقت نفرین را مثل Captain Tokka نمی‌فهمد!" }
WoWFQ[94802] = { t = "مرگ از میان مردگان", d = "Ssak'mozek همیشه سه سر دارد. طعمهٔ Captain Tokka نشانه‌رفته به هر سه سرش است.\nتکهٔ بعدی طعمه، مهره‌های شبح‌مانندِ ارواح جزیره است. میان این‌جا و آن‌سو موجودیت دارند و به‌گونه‌ای می‌درخشند که هیدرا نمی‌تواند نادیده‌شان بگیرد.\nاین مهره‌ها را در Crypt of the Lost Mason پیدا می‌کنی. حواست باشد--ارواح دوست ندارند وارد آن مکان شوی.", o = { "Ethereal Bead Strand" }, p = "Captain Tokka دوست دارد بگوید «در ماهیگیریِ زهر هیچ تابویی نیست». و البته حق دارد! اما اگر کمی نگران گورشکانی هستی، خودم مدام در آن سردابه کَندوکاو کردم. آن مهره‌ها بیشتر روح‌اند تا یادگار واقعی.", c = "می‌بینی مهره‌ها بی‌هیچ نوری می‌درخشند؟ Ssak'mozek از عمق خیلی زیر آب هم می‌تواند ببیندشان. بو، دید... دو تکه از طعمه آماده است." }
WoWFQ[94803] = { t = "در پی تاج", d = "تکهٔ آخر طعمهٔ هیدرای Captain Tokka پرهایی از خود کودکان Ula'tek است.\nSsak'mozek آموخته به فرمان این هیولاها گوش بدهد. در اعماق تیره در کمین می‌ماند تا آن‌ها صدایش کنند. طعمه بدون چیزی که به Ssak'mozek گره بزند به اربابانش کار نمی‌کند.\nهر یک از کودکانِ Gate of the Eastern Fang پرهایی دارد که برای طعمه عالی است. هر چه می‌توانی بیاور.", o = { "Vibrant Crownfeather" }, p = "تکهٔ آخر طعمهٔ Ssak'mozek را داری؟ پر لازم داریم--هر چه درخشان‌تر، بهتر.", c = "همه‌چیز آماده است. طعمه را می‌سازم. بعد، سراغ آن هیولا می‌رویم!" }
WoWFQ[94804] = { t = "گنجینهٔ تازه، غارت‌شده", d = "آخرین‌ها کمتر شده ماهی‌های سمت جنوب Atal'Utek؟ کار انبارکننده است.\nیک غول دریایی بزرگ و زشت است که نمی‌توانیم از شرش خلاص شویم. وقتی تپه‌های ماهی‌های مردهٔ در حال پوسیدن دیدی، یعنی پیدایش کرده‌ای.\nکاری کن دو بار فکر کند قبل از این‌که زیادی از این آب‌ها بردارد.", o = { "Hegvosh the Hoarder کشته‌شده" }, p = "انبارکننده در ماهیگیری‌اش حسابی نیست. هر چه شنا کند می‌کشد، نفرین داشته باشد یا نه.", c = "انبارکننده را کشتی! تا وقتی سیر و ساپرت ماهی بگیریم پنجره باز است، به لطف تو. بهتر است سریع بروی بیرون!" }
WoWFQ[94805] = { t = "شکارچیان غیرمجاز", d = "کودکان Ula'tek ماهی‌های نفرین‌زهر را مستقیم از آب می‌خورند. حالا که ماهی‌ها را قوی‌تر کردیم، وارد نوعی آشوب خوردن شده‌اند!\nCaptain Tokka می‌گوید جلوی شکار غیرمجاز گرفته شود. کودکان به‌اندازهٔ کافی زهر دارند!", o = { "Children of Ula'tek کشته‌شده" }, p = "هنوز می‌بینم شکارچی‌های غیرمجاز می‌گردند. می‌توانی چند تای دیگر را بفرستی؟ دوست ندارم این‌قدر نزدیک اردوگاه‌مان باشند!", c = "هیس‌های خشمگین‌شان از همین‌جا به گوشم می‌رسید، <name>! امیدوارم کودکان Ula'tek مدتی از جای ماهیگیری‌مان دور بمانند." }
WoWFQ[94806] = { t = "خزنده و خیس", d = "Captain Tokka می‌خواهد برای Ssak'mozek ماهیگیری کنیم.\nکودکان Ula'tek هیدرایی پرخاش‌تر و نفرین‌زهرتر از همهٔ بقیه پرورش می‌دهند. قبلاً هم گرفته‌ایم و کشته‌ایم، اما همیشه یکی دیگر می‌پرورند و همان اسم را می‌گذارند: Ssak'mozek.\nمی‌خواهیم یکی از بهترین طعمه‌های Tokka بسازیم تا آن را بکشیم.\nاول، پاهای زالو جمع کن. وقتی بشکنند بویی دارند که کودکان و ساخته‌هایشان نمی‌توانند مقاومت کنند.", o = { "Pungent Leech Leg" }, p = "تا می‌توانی پاهای زالو را نشکن. باید درست قبل از ساخت طعمه بشکانیم تا بویش تازه باشد.", c = "این‌ها حسابی کار راه‌اندازند! Ssak'mozek زیر آب کمین کرده. بوی این پاهای زالو کمکش می‌کند سمت تو کشیده شود." }
WoWFQ[94876] = { t = "پشتی‌بانی", d = "تیغ‌های ستون فقرات گراز بهترین سرنیزه را می‌سازند. برایمان بیاور.", o = { "Pristine Spinal Barb" }, c = "یک رگبار از تیغ‌های ستون! Mado-ru، hash'ura." }
WoWFQ[94936] = { t = "پیوند برادری", d = "من و برادرم Tekkan عضو یک تیم بودیم. دوستمان Kariz در جنگ با مارها کشته شد.\nبرادر کوچک‌تر Kariz، Jabat، از انتقام بلعیده شده. کوچک است و عجول، کور به عواقب کارهایش. زد بیرون تا مارها را بکشد. در خطر بزرگی است.\nRoldan حاضر نیست تیم نجات بفرستد و نمی‌گذارم مادرشان دوباره گریه کند. می‌رویم Jabat را بیاوریم.\nباید برای بعد از پیدا کردن Jabat مسیر فرار بچینیم. Tekkan با مواد منفجره‌اش از پس لانه‌های مار برمی‌آید، اما به یک بازوی قدرتمند نیاز داریم. هستی؟", o = { "لانهٔ مار اول نابود شد", "Clone Switch", "با Tekkan دربارهٔ لانهٔ دوم صحبت کن", "لانهٔ مار دوم نابود شد", "با Tekkan دربارهٔ لانهٔ سوم صحبت کن", "لانهٔ مار سوم نابود شد" }, c = "باز هم لانهٔ مار. باید راه پیش‌رو را برای پیدا کردن Jabat باز کنیم!" }
WoWFQ[94937] = { t = "خیلی ساکت در جبههٔ شمالی", d = "فقط یک مواد منفجرهٔ کوچک برایم مانده. حتی اگر Aol'ggin دربارهٔ روش‌هایم حق داشته باشد، دیگر نمی‌توانیم برگردیم. من...\n<Tekkan chokes on his words, then clears his throat.>\nمی‌توانیم. تو مارها را بیرون می‌کشی و حسابشان می‌کنی تا من امن لانه را بترکانم. بعد از آن، مسیر فرار باز می‌شود.", o = { "لانه نابود شد", "از کمین جان سالم به در ببر" }, c = "من... نمی‌دانم آن‌جا چه اتفاقی افتاد. متأسفم، <name>.\nبا رفتن لانه‌ها و نیروهای کمکی، آن مارِ بزرگ آن‌جا... همان است که... Kariz را کشت.\n<Tekkan's empty gaze is fixed on the large snake as his breathing becomes heavier and his posture stiffens.>" }
WoWFQ[94941] = { t = "نجات سرباز تازه‌کار Jabat", d = "آن مار بزرگ همان بود که Kariz را کشت. و حالا می‌بینم Jabat زخمی است و در خطر. Tekkan جواب نمی‌دهد. نمی‌دانم مشکلش چیست. وقتی برای تلف کردن نیست و نمی‌خواهم بپرسم چه بلاهای دیگر سر راه است. بخت بد است.\nیا به Jabat سر بزن یا همان اول برو سراغ آن مار بزرگ. هر کدام را اول انتخاب کنی، آن مار بزرگ باید بمیرد.", o = { "با Jabat صحبت کن", "Hiss'mir را شکست بده" }, c = "خیلی از رفقا در این دره مردند. برادرم Tekkan و بقیه...\n<Aol'ggin shakes his head.>\nحالا با loaها نشسته‌اند.\nیک روز من و Jabat هم به آن‌ها می‌پیوندیم. اما نه امروز." }
WoWFQ[94967] = { t = "حملهٔ گرسنگی Ki'clak", d = "به مردگان احترام می‌گذاریم، اما اکتوپلاسم کاربردهایی دارد. از آن‌های خشن جمع کن.", o = { "Swirling Ectoplasm", "Ki'clak Snack به دست آمد", "Ki'clak تغذیه شد" }, c = "خوب کار کردی. حالا ارواح نمی‌توانند به سربازهایمان آسیب بزنند." }
WoWFQ[94996] = { t = "نگاه مردگان", d = "مارها به گورهای نیاکانمان بی‌حرمتی می‌کنند. گردن‌آویزهای مقدسشان را پس بگیر.", o = { "Dehydrated Troll Eye Necklace" }, c = "جای مناسبی برای این یادگارها پیدا می‌کنم. ممنون." }
WoWFQ[95206] = { t = "شکستن تیغ", d = "با علامت Liadrin، وارد میدان می‌شویم و خودمان را از خطوط مقدم فرقه‌ای‌ها رد می‌کنیم.\nهنوز نمی‌دانند که این‌جاییم. سریع و خشمگین می‌زنیم. خطشان را می‌شکنیم و پیش از آن‌که بفهمند رسیده‌ایم، به داخل معبد می‌جنگیم.\nهر چه می‌توانی از آن‌ها بکش. راه ورودمان به معبد را باز کن.", o = { "آشفتن Twilight's Blade" }, c = "آفرین، <name>. اکثر آدم‌ها فرقه‌های مرگ را در دل کابوس‌هایشان می‌بینند، اما شاید فرقه‌گراهای مرگ کابوس از تو ببینند." }
WoWFQ[95208] = { t = "پشت به پشت", d = "بدون دادن خبر رسیدیم جزیره. اما لحظه‌ای که از آن دیوار رد شویم، جهنم شروع می‌شود.\nاصلاً هم‌نظر نیستیم، اما ما تنها چیزی هستیم که میان سرزمین اصلی و نابودی کامل فاصله انداخته. تهدید آن‌قدر بزرگ است که باید کنار هم بیاییم تا هر دو خاکمان را از فاجعه نجات دهیم.\nتو همیشه نیرویی پیوسته بوده‌ای، <name>. مطمئن شو همهٔ متحدانمان آن بالا در امنیت بمانند.", o = { "Dak'zor و Arator یاری شدند", "Lor'themar و Zul'jarra یاری شدند", "Tak'lejo و Halduron یاری شدند", "Liadrin و Orweyna یاری شدند" }, p = "متحدانمان همدیگر را دوست ندارند. هیچ توهمی درباره‌اش ندارم، اما ایمان دارم حتی آن‌ها هم می‌توانند زیر فهم مشترک و دشمن مشترک یکی شوند.", c = "در تمام عمرم فکر نمی‌کردم شاهد چیزی باشم که امروز می‌بینیم، <name>. Amani‌ها و sin'dorei‌ها، سرِ شانه به شانه...\nوقت سنت‌گرفی نیست. هنوز از مهلکه بیرون نیامده‌ایم." }
WoWFQ[95209] = { t = "صدای ناشنیده", d = "بیشتر عمرم را صرف امنیت Quel'Thalas کردم. ترول‌های زیادی کشته‌ام. ترول‌ها هم خیلی از بهترین Farstriderهایم را کشته‌اند. نمی‌دانم بعد از تمام آن‌ها، بعد از تمام کارهایی که کرده‌ایم، بتوانیم هرگز واقعاً همدیگر را بفهمیم.\nاما همین حالا هیچ‌کدام مهم نیست. شاید ایمانِ Liadrin به صلحی پایدار با Amani‌ها را نداشته باشم، اما اگر Twilight's Blade را همین‌جا متوقف نکنیم، هرگز فرصت فهمیدنش را هم پیدا نمی‌کنیم.\nرهبرشان را پیدا کن. کاری را که باید انجام بده.", o = { "Interlocked Twilight Runes", "Twilight Barrier نابود شد" }, p = "هر چه بیشتر این‌جا معطل شویم، ریسک فاجعه بیشتر است.\nتمامش کن. سریع.", c = "بدون رهبرشان، فرقه مدتی یکپارچه نمی‌ماند، اما تهدید اصلی هنوز پابرجاست." }
WoWFQ[95210] = { t = "در دهان دیوانگی", d = "نبرد را بردیم، اما جنگ باقی است. از بین بردن Twilight's Blade برای بیدار نشدن Kith'ix کافی نیست.\nباید پیش از آن‌که کل این مکان فروریزد، راه ورودی به لانه‌اش را پیدا کنیم.\nبا احتیاط پیش برو، <name>. حس می‌کنم چشم شکارچی‌ها از هر سایه‌ای کمین کرده.", o = { "جسدها بررسی شدند", "راهرو ورودی کشف شد", "تپهٔ مرکزی گشت شد", "پله‌های شرقی کشف شد", "تالار شرقی کشف شد", "پل فروریخته امن شد" }, c = "تقریباً نشانه را پیدا کردیم، اما Dak'zor فقط برای همین پیشرفت جانش را داد. اگر از اول با هم کار کرده بودیم...\nنه.\nحالا وقت لرزیدن نیست. نمی‌گذاریم قربانی Dak'zor بیهوده شود." }
WoWFQ[95211] = { t = "رهاسازی Kith'ix", d = "در زندگی‌ام چیزهای ناممکن زیادی دیده‌ام، اما شاهد ایستادن الف‌ها و ترول‌ها سرِ شانه به شانه در دفاع از خاک‌هایمان...\nحالا وقت لرزیدن نیست. نباید حالا لرزید.\nشانسی برای صلحی طولانی میان قوم‌مان در میان است، <name>. اما اگر Kith'ix از لانه‌اش بیرون بیاید، هرگز فرصت دراز کردن دست به سویش را پیدا نمی‌کنیم.\nKith'ix باید بیفتد. هر قیمتی که داشته باشد.", o = { "کمی بمان و گوش کن", "رید Unbinding of Kith'ix را در هر درجهٔ سختی کامل کن", "برای ورود به رید در حالت داستانی با Lady Liadrin صحبت کن" }, p = "خودِ Kith'ix بی‌شک در تالارهای پایین در انتظار ماست. نبرد نهایی نزدیک است.\nخوشحالم که با تو این‌جایم، رفیقم. با هم، Quel'Thalas و Zul'Aman را نجات می‌دهیم.", c = "Quel'Thalas امروز نمی‌افتد. Zul'Aman هم.\nقوم‌مان خواهند فهمید امروز این‌جا چه گذشت. حواسم هست." }
