WoWFQ[95520] = { t = "پاک‌سازی خزانه‌ها", d = "شیاطین این معبد دوست دارند همه‌مان را بکشند. ما تنها چیزهایی هستیم که میان آن‌ها و سرزمین اصلی فاصله انداخته‌ایم، می‌فهمی؟ همین‌جا حبسشان کرده‌ایم.\nیک فلس، یک انگشت استخوانی، هیچ‌کدامشان نمی‌روند بیرون از این معبد وقتی ما نفس می‌کشیم.\nبرو بیرون و بریدشان بزن.", o = { "انجام فعالیت‌ها در Vaults of Atal'Utek" }, p = "روح‌هایشان را با ناله به سمت Ula'tek پس بفرست.", c = "شیاطین این‌جا از کثیف‌ترین و پست‌ترین موجودهای Azeroth هستند. و فکر کنم دارد از تو می‌ترسند.\n<Abdumati smiles.>\nاگر از این ماجرا جان سالم به در ببریم، برایت ترانه می‌سازند." }
WoWFQ[95521] = { t = "مدال Med'jai", d = "<The ancient gem pulses faintly. Scratches adorn its sides as if pried away with desperate eagerness. Perhaps the troll spirit, Me'si, will know where this came from.>", c = "از وقتی در سرزمین زندگان قدم می‌زدم، چنین چیزی ندیده بودم.\nباور دارم یکی از مدال‌های گرامی Med'jai را پیدا کرده‌ای، متعلق به جنگجویان قهرمانی که باور بر این بود با تمام وجود از این معبد محافظت می‌کنند." }
WoWFQ[95522] = { t = "نگهبانان مرگ، نگهبانان سنگی", d = "در افسانه‌هایی که به ما رسیده، از گروهی از نگهبانان قهرمان حرف می‌زنند که قربانی‌شان تا امروز از ما محافظت کرده. این معدود گرامی، همان‌های Med'jai، کمربندهایشان را با سنگ‌هایی مثل این‌ها آراسته بودند--تا بهتر دشمنانشان را بکشند و شکستشان بدهند.\nبه ما گفتند به سفری بزرگ برای جنگ با شرارت‌های بیرون رفتند، اما به‌نظر می‌رسد بزرگ‌ترین شرارت‌ها در درون بود--زیر پای خودمان.\nلطفاً، <name>، دنبال خانهٔ اصلی این سنگ بگرد. اگر ارواح نیاکان ما مراقبمان باشند، شاید جای آرامگاهشان را پیدا کنیم.", o = { "مجسمهٔ جنگجوی Amani پیدا شد", "Med'jai Medallion به مجسمه رساند", "کتیبه وارسی شد" }, c = "می‌بینم خیلی چیزها عوض شده، gokinye.\nبه‌عنوان یک جنگجو، در میدان نبرد برای Amani‌ها جنگیدم. تیغم میان دشمنانمان وحشت‌انگیز بود.\nوقتی قومم از من خواست از این معبد محافظت کنم، اولین کسی بودم که قدم جلو گذاشت. افتخاری بالاتر از جان دادن برای قومت نیست. و به این افتخار می‌کنم.\nاما حالا که دور و برم را نگاه می‌کنم، در دلم می‌پرسم. نکند قربانی‌مان بیهوده بود؟" }
WoWFQ[95523] = { t = "لایقِ گذشته", d = "Soulcoilerها باید تاوان بدهند، <name>.\nSoulcoilerها باور داشتند کارهایشان Amani‌ها را نجات می‌دهد. در عوض، قوم و آینده‌مان غارت شد. تا وقتی دیر شده بود نفهمیدیم.\nتمامشان کن. حتی روحشان را بشکن، به‌گونه‌ای که حتی Mueh'zala بزرگ نتواند سر همشان کند.", o = { "Soulcoiler Souls نابودی شد" }, p = "شکست کافی نیست، <name>. خودِ روحشان را نابود کن.", c = "این خوب است. روح‌های نفرین‌شانشان فقط ابهام را خواهند شناخت." }
WoWFQ[95524] = { t = "فراموش‌نشده‌ها", d = "من تنها Med'jای نیستم که مأمور نگهبانی از کاهنه‌ها شده بود. ما سه نفر بودیم، در سنگی هم‌شکل قیافهٔ زندگی‌مان به خاک سپرده شده‌ایم.\nباید بدانم هنوز آن‌جایند یا نه. کمکم می‌کنی پیدایشان کنم؟ بدنم در این سنگ بسته است، اما روحم نیست. سنگم را به آن مکان‌ها ببر، اگر پیدایشان کردی.\nاگر نتوانیم بیدارشان کنیم، دست‌کم ارج‌شان خواهیم نهاد.", o = { "The Statue of Let'aka ارج نهاده شد", "The Statue of Gal'fon ارج نهاده شد" }, p = "پیدایشان کردی، <name>؟ برادران و خواهرانم.", c = "ممنونم، <name>. آرزویم بهتر از این بود، اما فهمیدن سرنوشتشان در این دنیا آدم را آرام می‌کند." }
WoWFQ[95525] = { t = "بیداریِ شایسته", d = "معبد از وقتی کشیکم را شروع کردم عوض شده، <name>. وقتی اولین بار بیدارم کردی، همه‌چیز که می‌دیدم فساد و ارواح ناپاک بود. نتیجهٔ ضعف ما.\nحالا می‌بینم که شکست نخورده‌ایم. میدان نبرد عوض شده، مثل همیشه که عوض می‌شود.\nلطفاً سنگم را بردار و پیش بقیه مثل خودت برگردان. شاید روحم بتواند در این میدان تازه، به شیوه‌ای تازه، نیرویی برای خیر شود.", c = "آه، صدای Thaze'ala را می‌شنوم. روح قهرمانانه‌اش را در این سنگ بیدار کردی، <name>.\nشاید با حکمتش خیلی چیزها بفهمیم؛ مثلاً این‌که ننگ بزرگ‌مان فقط با قربانی قهرمانانهٔ قوممان مهار شده بود." }
WoWFQ[95529] = { t = "نیزه‌کُشی مارهای آسمانی", d = "نمی‌شود گذاشت کودکان Ula'tek خطوطشان را قوی‌تر کنند. از آسمان نوکشان بزن!", o = { "Scaleskin Harrier کشته‌شده" }, c = "هر مار مرده یک قدم به پیروزی است." }
WoWFQ[95564] = { t = "دُم مار", d = "شمن‌های Shadowpine فرمان hash'ey ما را اجرا می‌کنند. ما زبان آتش را از بال Jan'alai حرف می‌زنیم، اما کمک هم می‌خواهیم.\nبا کمک قبیله‌های دیگر، این اردوگاه را امن کردیم. اما بدون کمک تو زیاد سر پایش نمی‌مانیم.\nچند کار هست که از تو می‌خواهم، hash'ura، اگر میل داری.", o = { "پرچم کاشته شد", "سنگر نابود شد", "ستون ویرانی نابود شد", "تندیس منحرف نابود شد", "Caustic Abductor کشته‌شده" }, p = "بدون این پایگاه، هرگز جای پای کافی پیدا نمی‌کنیم تا جلوی حملهٔ هیولاها به بقیهٔ Zul'Aman را بگیریم.", c = "Mado-ru، hash'ura، که امن کردن اردوگاهمان کمک کردی.\nحالا می‌توانم در سخت‌ترین لحظه به hash'ey کمک کنم." }
WoWFQ[95662] = { t = "خورشتی مشکوک", d = "جنگجویانمان باید سیر شوند، اما موادی که داریم... عجیب‌اند. ببین چه می‌توانی درست کنی، خب؟", o = { "با آشپز Witherbark صحبت کن", "یک «وعدهٔ جنگجویی» درست کن" }, c = "بویی جالب دارد، به هر حال! سربازها یکی‌جوری سر پا می‌شوند." }
WoWFQ[95794] = { t = "فرایند رمزگشایی", d = "این گردن‌آویز روح را تشویق می‌کند جلوتر برود... یا ممکن است عصبانی‌شان کند. ارزش امتحان دارد!", o = { "ارواح رمزگشایی شدند", "De-cryption Amulet" }, c = "بهتر از چیزی پیش رفت که فکر می‌کردم. Jan'alai حتماً تماشا می‌کند." }
WoWFQ[95804] = { t = "کودکان Ula'tek", d = "این tortollanها گم شده‌اند؟ چقدر است این‌جایند؟\nیک آبادی از آن‌ها نزدیک Shrine of Filo داریم، اما این‌جا جایی نیست که باید باشند.\nروزی که خیلی دور نیست، رانده‌بودم‌شان. اما این اواخر شانس خوبی با غریبه‌ها داشته‌ایم.\n<A hint of a smile crosses Zul'jarra's face. It's the first you've seen since before Malacrass's return.>\nباید با آن‌ها حرف بزنیم. شاید بدانند این ماجرا از کجا شروع شد.", o = { "با Captain Tokka صحبت کن" }, p = "اگر می‌خواهیم قوممان را پیدا کنیم، باید بیشتر دربارهٔ این جزیره بدانیم.", c = "Zul'jan...\nچرا چنین کاری کردی، برادر؟" }
