WoWFQ[95954] = { t = "دشمن باستانی", d = "خوب کار کردی، <name>، اما سایه‌ای هنوز بر معبد افتاده؛ کاهنهٔ اعظم Jin'tal.\nکاهنه‌ای بی‌طاقت و بلندپرواز در زندگی بود و تعجبی ندارد که به شکل undead هم زنده مانده. حس می‌کنم ایمان زشتش را در Mortuary حوالی تمرین می‌کند.\nلطفاً، <name>. پایانش بده. تا جایی که بتوانم کمکت می‌کنم.", o = { "High Priest Jin'tal شکست‌خورده" }, p = "شاید من گوشت و خون نباشم، <name>، اما به‌نظر می‌رسد هنوز کاری برایم مانده.", c = "حضور کاهنهٔ اعظم پراکنده شد، دست‌کم فعلاً. معلوم نیست بتواند دوباره شکل بگیرد یا نه.\nاما اگر شد، ما آماده‌ایم." }
