WoWFQ[96089] = { t = "یک چیز درست نیست", d = "هر چه با او شده، هر کاری که آن موجودها کرده‌اند، باید درمانش کنم!\nکمک می‌کنی؟", o = { "Medic La'una وارسی شد", "با دیده‌بان Oma'ema صحبت کن", "از Apothecary Dezi کمک بگیر" }, p = "در این جزیره هیچ روزی مثل روز قبلش نیست.", c = "این دستور یک قی‌آور است. معجون استفراغ.\nهیچ درمانی بهتر از این نیست که هر چه بدنش را گرفته بالا بیاورد." }
WoWFQ[96090] = { t = "زهرِ قی", d = "بقیهٔ مواد قی‌آور را همین‌جا دارم. آخرین ماده، مقداری زهر است که واکنش را راه بیندازد.\nاز قول ترول‌ها شنیدم از همین شمال جایی هست به اسم Serpent's Tail. می‌گویند پر است از بدهاِ زهرآگین، اما ما فقط به زهر کودکان Ula'tek نیاز داریم.\nمی‌گویند حتی رودهایی از همین ماده خورنده پر است، اما توی آن‌ها شنا نکن. آن‌قدر غلیظ است که پیش از آن‌که فریاد بزنی «دارم آب می‌شوم!»، بطری جمع‌آوریت را می‌خورد.", o = { "Virulent Ula'tek Venom", "Dezi's Potion Bottle" }, p = "همه‌اش را گرفتی؟ به‌نظرم دوستت وقتی زیادی ندارد.", c = "آره، این حسابی کار را راه می‌اندازد. اوه، ولی این بوی سمی!\nآماده‌ای در ساخت قی‌آور کمکم کنی؟" }
WoWFQ[96091] = { t = "درست گرفتن میزان", d = "سه بطری با مواد مختلف آماده کرده‌ام. فقط کافی است مقدار درست را اضافه کنی... کمی زهر در هر کدام. میزانشان را تنظیم کن.\nمی‌توانی از دیگ Ofi همان‌جا استفاده کنی. مطمئنم دلش نمی‌گیرد. هر چه داخلش است احتمالاً از قبل از تولدش دارد می‌جوشد.\nنه، قرار نیست خودم برایت انجامش بدهم. آن‌قدر زندگی کرده‌ام که بدانم دست به آن ماده نزنم!\nوقتی نتیجه را گرفتی، قی‌آور را به دوست دکترت بده و ببینیم چه می‌شود.", o = { "Dezi's Emetic ساخته شد", "Dezi's Emetic خورانده شد", "وضعیت La'una وارسی شد", "با دیده‌بان Oma'ema صحبت کن" }, p = "خب، معطل نگذار. معجون را ساختی؟ بهش دادی؟ کار کرد؟", c = "حیف شد. از همین‌جا صدایش به گوشم می‌رسید، موجود بیچاره.\nراستش چون این کار نکرد، ایدهٔ دیگری دارم، هرچند سخت‌تر است. برای کمی ماجرای بیشتر حوصله داری؟" }
WoWFQ[96092] = { t = "آن احمق، Ruma", d = "متأسفانه ماجرا از تخصص من خارج شده.\nخوشبختانه کسی را می‌شناسم که می‌تواند کمک کند. احتمالاً.\nبدشبختی، برای یک «ماجرای بزرگ» به جزیرهٔ Gnarldor در جنوب رفته. بیشتر احتمال دارد در یک عطسهٔ بزرگ باشد.\nبگیر، این اکسیر را بده به دکتر کشتی سابق‌مان، Ruma. همیشه یکی از این‌ها در جیب دارم. حسابی سرحالش می‌کند.\nبعد، به عهدهٔ خودت است قانعش کنی درمانی طراحی کند. موفق باشی!", o = { "Scrollmaster Ruma پیدا شد", "Sobering Elixir" }, c = "خب، این حسابی بی‌ادبی بود. شاید لازم، اما بی‌ادبی به هر حال.\nهم... یک رد بادمجان حس نمی‌کنی؟\n<Ruma smacks his lips.>\nاین اکسیر قطعاً کار Dezi است. خوشمزه است، اما حیرتم که این میوهٔ شگفت و کمیاب را از کجا تهیه کرده." }
WoWFQ[96093] = { t = "این کوله است، کیف نه", d = "خب، می‌بینی، من همراه رفیقم Tormunda و چند نفر دیگر در ماجرای بزرگی بودم. گشتن در دنیا، نوشیدنی‌های عجیب، استراحت و تفریح. اما بعد، بلا سر اردوگاهمان آمد.\ngnarldinها!\nاز هم جدا شدیم و من کاری را کردم که وقتی گم می‌شوی باید کرد: سر جایت بمانی. پس این‌جا مشغول استراحتم.\nاما می‌ترسم در وسط این غوغا، کوله‌ام جا مانده. همهٔ بهترین وسایلم داخلش است.\nمی‌بینی، اگر کمکم می‌خواهی، باید بروی و برایم بیاوری‌اش.", o = { "Ruma's Satchel" }, p = "کوله‌ام را پیدا کردی؟ همهٔ بهترین نوشیدنی‌هایم... یعنی، طومارهایم داخلش است.", c = "خب، خوب است. نگران بودم غارت شده باشد. ممنون، <name>.\nحالا، می‌خواستی بگویی دوستی در نیاز به درمان است؟" }
WoWFQ[96094] = { t = "به سوی Forum", d = "اگر بخواهیم به La'una این‌تان کمک کنیم، باید به سرچشمه برویم. گفتی داشتند لبهٔ غربی Fangs را دیده‌بانی می‌کردند که ماجرا پیش آمد؟\nهمه می‌دانند کسی آن‌جا نمی‌رود. نباید آن‌جا برویم. اما دقیقاً همان‌جایی است که باید برویم، چون درمان همان‌جاست.\nیا، مرگ ما همان‌جاست. هر کدام زودتر برسد.\n<Ruma begins rummaging through his pack for a refreshment.>", c = "به تو گفتم زودتر از تو می‌رسم. این قدرت طومارکیمیاست، رفیقم.\nخوب شد که دیده‌بانت همین‌جا بود. این جایی نیست که آدم تنها گیر بیفتد!" }
WoWFQ[96095] = { t = "چشیدن به حیات وحش محل", d = "اگر بخواهم درمانی طراحی کنم، به نمونه نیاز دارم و فراوان.\nشانس‌مان که هر دو چیزی که لازم داریم موجود است: تو و همهٔ حیات وحشِ آلوده‌ای که این‌جا می‌گردد.", o = { "Infectious Wildlife Sample", "نمونه‌ها رسانده شد و طومار درمان ساخته شد" }, p = "این اولین قدم در یافتن درمان برای هر چه بیرون این‌جا می‌گذرد.", c = "راستش نمی‌فهمم این‌همه غوغا برای چیست. هر آزمایشی خطا و لغزش دارد. من خوبم.\nمهم این است که حالا بیشتر از لحظه‌ای پیش می‌دانیم." }
WoWFQ[96096] = { t = "گروه دیده‌بانی هفت", d = "وقتی اولین بار به این‌جا آمدیم، رهبرمان، Dusk Prowler Hano'mon، گروه را زیادی داخل برد. او همیشه یک... خیلی محبوب نبود.\nمن عقب را دیده‌بانی می‌کردم و وقتی به La'una رسیدم، او قبلاً تحت تأثیر هر چه این است بود.\nممکن است بقیهٔ گروه دیده‌بانی‌ام هنوز بیرون باشند. اگر هستند، باید سرنوشتشان را بدانم، هر چه که باشد.\nاسم‌هایشان A'pone، Kamaina، Ko'ruku، Uha'ne و Hano'mon است.", o = { "Dusk Prowler Hano'mon پیدا شد", "دیده‌بان Kamaina پیدا شد", "دیده‌بان Ko'ruku پیدا شد", "دیده‌بان Uha'ne پیدا شد", "Wartusk A'pone پیدا شد", "تکه‌های گردن‌آویز Uha'ne", "گردن‌آویز A'pone" }, p = "کل این اردوکشی از اول اشتباه بود. Hano'mon زحمت تحقیق نداد قبل از این‌که ما را این‌جا بیاورد.", c = "<Oma'ema reaches out her hand to take the necklaces.>\nممنونم، <name>." }
WoWFQ[96097] = { t = "آنچه دیده‌بان‌ها دیدند", d = "اگر حدسم درست باشد، فکر کنم می‌دانم چه چیزی کم داریم.\nمی‌شود لطف کنی از این دیده‌بان‌ها بپرسی آن‌جا چه دیدند؟ مشکوکم خودشان از قبل می‌دانند چه چیزی، یا چه کسی، پشت این ماجراست.", o = { "با دیده‌بان Kamaina صحبت کن", "با دیده‌بان Ko'ruku صحبت کن" }, p = "بعد از این‌که هر دو گزارش را گرفتی، حرف بزنیم.", c = "با گزارش‌های دیده‌بانی‌شان هم‌نظرم. حالا وقت اقدام است." }
WoWFQ[96098] = { t = "واکنشگرهای نهایی", o = { "Tetla'ketl's Conjuring Crest", "Tsssaani's Scales of Summoning", "واکنشگرها رسانده شد و طومار درمان ساخته شد" } }
WoWFQ[96099] = { t = "سرنوشت La'una", d = "نسخه آماده است. حالا فقط کاری که مانده، کاری که «تو» باید بکنی، دادن آن به بیمار است.\nنگران نباش، کار می‌کند. مطمئنم. خب، بیشترِ بیشترم مطمئنم. بگوییم شصت‌وهفت درصد مطمئنم. با توجه به جایگزینش، شانس بدی هم نیست.", o = { "طومار Ruma را روی Medic La'una استفاده کن", "Ruma's Infestation Eradicator" }, p = "امیدوارم کار کند.", c = "تو و دکتر بهترین هستید!\nهر وقت چیزی خواستید، می‌توانید روی گروه دیده‌بانی هفت حساب کنید، یعنی... چهار." }
WoWFQ[96110] = { t = "ماهیگیریِ زهر: اثبات در لجن است", d = "اگر می‌خواهی جزو خدمهٔ من باشی، بهتر است آمادهٔ دست و پنجه نرم کردن با نفرینِ زهر باشی.\nماهیگیری بلدی؟ هر موجودی که روی این جزیره آبشش دارد آماده است دندان در تو فرو کند.\nثابت کن حتی کوچک‌ترین ماهی نفرین‌زهر را صید می‌کنی تا راه ماهیگیریِ کشنده‌تر و زشت‌تر را به تو نشان بدهم.", o = { "از Second Mate Sluggs ماهیگیری یاد بگیر", "Venom-Cursed Killifish" }, p = "این کیلی‌فیش‌ها همان‌هایی هستند که کودکان تازهٔ Ula'tek بعد از بیرون آمدن از جسدت می‌نوشندشان. اگر نمی‌توانی رامشان کنی، برای Great White Serpent هیچ شانسی نداری.", c = "اولین صید خوبی است. اگر معده‌ات لطیف باشد، چند راز دیگر هم برای گرفتنشان به تو می‌گویم." }
WoWFQ[96111] = { t = "ماهیگیریِ زهر: پوستهٔ خودت", d = "چند تا از رازهای ماهیگیری در این آب‌های نفرین‌شده را یاد گرفتی، اما هر چه از این به بعد یاد می‌گیری برای هدفی بزرگ‌تر از بقا است.\nانتقام.\nGreat White Serpent که کشتی‌ام را غرق کرد هنوز زنده است. اگر قصد کشتنش داریم، به قدرت خدمه‌ام نیاز داریم، که حالا قربانی نفرین‌زهر شده‌اند.\nMaster Grenadier Birdie فقط یک شانس خوب دارد: شلیک اولش. برای خودت یک فریب‌نده بساز تا شانسی برای کشتنش پیدا کنی.\nمواد منفجره‌اش را بردار. برای متلاشی کردن آن مار لازمشان داریم.", o = { "Wood Debris", "تودهٔ Wood Debris ساخته شد", "فریب‌ندهٔ تو ساخته شد", "Birdie's Bombardment Pack" }, p = "Birdie از هر چیزی می‌توانست مواد منفجره بسازد. دلم نمی‌خواهد حالا که ذهنش پر از زهر است به او نزدیک شوم.", c = "دقیقاً همان‌طور است که گمان می‌کردم. Birdie همهٔ این سال‌ها دست نگه می‌داشت و حالا زهرش را از کنترل‌های اخلاقی‌اش آزاد کرده.\nاز ابزارهای کج‌وش او برای هدفی خوب استفاده می‌کنیم: نابود کردن آن مار نفرین‌شده!" }
WoWFQ[96112] = { t = "ماهیگیریِ زهر: معجون دیوانگی", d = "برای روبه‌رو شدن با Great White Serpent چیزی لازم داریم که پشت بی‌پوستهٔ تو را محافظت کند.\nLeathertongue غذاهایی می‌پخت که ما را تقریباً در برابر هر چیزی مصون می‌کرد، البته به این دلیل که تقریباً هر وعده ما را می‌کشت!\nدیگ و تابه‌هایش در برابر هر کابوسی سرپا می‌ماند. به آن قدرت نیاز داریم.\nکلید شکست آشپز، چالش کشیدن مهارتش است. یک غذا از زشت‌ترین مواد درست کن، خودش می‌آید سراغت.", o = { "Tough Crab Meat جمع شد", "Resplendent Ectobarb جمع شد", "Souplrgr's Fine Breadcrumbs جمع شد", "دیگ خورشت Leathertongue پر شد", "دیگ یدکی Leathertongue جمع شد" }, p = "یک ماه تمام است دیگ Leathertongue خالی مانده. هر چه الان برای تمرین آشپزیِ زهرآلودش به کار می‌برد، حتماً تو را از مار محافظت می‌کند.", c = "می‌ترسیدم یک روز Leathertongue راهی برای کشتن خدمه با غذاهایش پیدا کند. این‌که آن احمق بیچارهٔ نفرین‌زهر را آرام کردی دلم را راحت کرد.\nدیگ یدکی‌اش کارکرده است. خوب به دردت می‌خورد." }
WoWFQ[96113] = { t = "ماهیگیریِ زهر: اوج قدرت", d = "تقریباً آمادهٔ روبه‌رو شدن با Great White Serpent هستیم. فقط یک چیز دیگر مانده.\nمی‌خواهم قایق رئیس تدارکاتم را ببری.\nInktail نقشه‌هایی روی نقشه دارد. پیش از زهر، حتی در طوفان‌های وحشتناک خونسرد و خوددار بود. با نفرین زهر، دست‌نیافتنی‌تر هم شده.\nفقط یک بار دیدم خونسردی کشنده‌اش بر هم بخورد. عشق بزرگی به ماهی‌های کمیاب دارد.\nقماری است، اما به داخل معبد برو و ماهیِ غرق در زهر پیدا کن. شاید برای بیرون کشیدنش از مخفیگاه کافی باشد.", o = { "از Gate of the Serpent's Eye وارد Vaults of Atal'Utek شو", "برای Venom-Charged Dubloon ماهیگیری کن", "Black-Venom Grouper جمع شد", "خروج از Vaults of Atal'Utek", "Black-Venom Grouper گذاشته شد", "قایق مقاوم Inktail گرفته شد" }, p = "بیشتر از هر کس دیگر، Inktail همان tortollanای است که هرگز خودم با او طرف نمی‌شدم. پارانویایش برای برنامه‌های دقیقش بیشتر از عمر من کار کرده.", c = "انجامش دادی. همه‌چیز برای روبه‌رو شدن با Great White Serpent را داریم.\nروزهای آن مار شمرده شده است." }
WoWFQ[96267] = { t = "سنگ‌های نیاکان", d = "وقتی کودکان Ula'tek این معبد را گرفتند، خیلی از نیاکانم با دفاع از آن مردند. یادگارهای مقدس به دست مارها افتاد! حتی همین حالا آن‌ها را به جادویی پلید بدل می‌کنند!\nمیان این‌ها سنگ‌هایی با قدرت بزرگ هم بود.\nخزانه‌ها، تالارهای آیینی و هر گوشهٔ عمیق معبد را بگرد و هر سنگی که پیدا کردی پس بگیر.", o = { "Ritual Gem", "Warded Key" }, p = "سنگ‌ها را پس گرفتی؟", c = "کودکان Ula'tek دیگر سر و کله با این سنگ‌ها پیدا نخواهند کرد. این کار را فراموش نمی‌کنم." }
WoWFQ[96271] = { t = "وجودِ نفرین", d = "وقتی زهر در این معبد پخش شد، خیلی از نیاکانمان با دفاع از این مکان افتادند.\nحالا Nek'zali روح‌هایشان را به بند کشیده تا در بازگرداندن Ula'tek به او خدمت کنند. به ارواح نفرین‌شده آرامش بده تا بتوانند از این مکان فراتر بروند.", o = { "Jarza the Cursed کشته‌شده", "Venom Revenant Zal'kir کشته‌شده", "Min'zu the Fangbound کشته‌شده", "Coil-Cursed Vok'tara کشته‌شده", "Shadowblade of Nek'zali کشته‌شده", "Nek'zali's Ensnared کشته‌شده" }, p = "با این تهدیدها حساب شد؟", c = "با این کار به نیاکان آرامشی بخشنده هدیه دادی." }
WoWFQ[96273] = { t = "توزانی که با خون پرداخت می‌شود", d = "کودکان Ula'tek توازن جهان روح را به هم زده‌اند. ارواح زیادی خشمگین‌اند و پیش از رفتن، دادخواهی می‌خواهند.\nخونِ مارها توازن را برمی‌گرداند!\nکودکان Ula'tek و هر کس که در این معبد به آن‌ها یاری می‌رساند را بکش.", o = { "کشتن دشمنان در Vaults of Atal'Utek" }, p = "این کار را کردی؟", c = "ارواح می‌بینند چه کردی، و حالا در توازنی که آوردی آرمیده‌اند." }
WoWFQ[96275] = { t = "گام در زهر", d = "روح‌های زیادی این‌جا به افسون‌های تاریک Nek'zali باخته‌اند، اما هنوز امید نجات بقیه هست.\nنگهبانان روح را در سراسر دریاچه‌های زهر بکار تا به ارواح نزدیک پناه بدهند.\nدریاچه‌های زهر کشنده‌اند، پس آماده برو!", o = { "Spirit Guardians گذاشته شد" }, p = "نگهبانان را گذاشتی؟", c = "ارواح برایم نجوا می‌کنند. از امنیتی که به آن‌ها می‌دهی شکرگزارند." }
WoWFQ[96276] = { t = "افسون‌های تاریک", d = "کودکان Ula'tek با ارواح این‌جا بازی‌های بی‌رحمانه‌ای می‌کنند. با افسون‌های تاریک آن‌ها را گرفتار و عذاب می‌دهند.\nافسون‌ها در سراسر معبد پنهان‌اند. پیدا کن و بسوزان تا ارواح این‌جا به آرامش برسند.", o = { "Dark Charms نابود شد" }, p = "افسون‌ها را نابود کردی؟", c = "ارواح نیاکان می‌بینند چه کردی و خشنودند!" }
WoWFQ[96305] = { t = "ذاتِ بی‌گناه", d = "وقتی مدافعان افتادند و به سرنوشتشان نفرین شدند، عقاب بزرگ Tok'jara که با آن‌ها پر می‌زد هم افتاد. چنین بی‌گناهی لایق این نفرین نبود.\nهمین حالا روحش می‌جنگد تا آزاد شود و فواره‌ای پیچان از برکه‌های زهر بالا می‌آید.\nکمکش کن آزاد شود، ذاتش را از زهر بگیر و به رنجش پایان بده.", o = { "ورود به Venom Geyser", "Essence of Tok'jara بازیابی شد" }, p = "Essence of Tok'jara را بازیابی کردی؟", c = "کار تو، <name>، دل این ترول پیر را گرم کرد. روح Tok'jara آزاد است و حالا کنار تو این دنیا را می‌گردد." }
WoWFQ[96349] = { t = "سنگ‌های نیاکان", o = { "30 سنگ Ritual Gem از ژرف‌ترین بخش‌های Vaults of Atal'Utek بازیابی کن." } }
WoWFQ[96352] = { t = "افسون‌های تاریک", o = { "20 افسون تاریک را که در سراسر Vaults of Atal'Utek پخش است بسوزان." } }
WoWFQ[96354] = { t = "توزانی که با خون پرداخت می‌شود", o = { "دشمنان را در Vaults of Atal'Utek بکش." } }
WoWFQ[96360] = { t = "گام در زهر", o = { "8 نگهبان روح را در نقاطی از زهر جا بده." } }
WoWFQ[96361] = { t = "وجودِ نفرین", o = { "Jarza the Cursed، Venomous Revenant Zal'kir، Coil-Cursed Vok'tara و دیگر خدمتکاران Nek'zali را بکش." } }
WoWFQ[96439] = { t = "قطع خبر", d = "این لانه‌های جهنمی جایی است که کودکان Ula'tek از آن‌ها سر برمی‌آورند. باید پاکشان کنیم تا امیدی به مهار سیل بی‌پایان مارها باشد.\nگروه‌هایی از بی‌باک‌ترین دیده‌بان‌هایم را فرستادم تا درباره‌شان اطلاعات جمع کنند. همه برگشتند... به‌جز یکی.\nبرو، Ulantu و Naj'kula را در Blistering Terrace دنبال کن. بفهم چرا خبرشان قطع شد.", c = "Kul'amara فرستاده؟\nبه ارادهٔ loa زبردست ما درود..." }
WoWFQ[96450] = { t = "از پهلو", d = "من و Naj'kula آمده بودیم ببینیم کودکان Ula'tek چطور تولیدمثل می‌کنند.\nاین لیش، Lokago، را پیدا کردیم. Malacrass او را مأمور آزمایش روی Amani‌های ربوده‌شده کرده بود. مدارکش را دزدیدم تا بفهمم چرا، اما لیش ما را کشف کرد. زخمی شدم. همه‌چیز را انداختم.\nNaj'kula درست پشت سرم بود... باید مدارک را پس بگیریم--و Naj'kula را پیدا کنیم!", o = { "یادداشت‌های آزمایش Lokago", "دفتر حساب Lokago", "نامه‌ای از Malacrass" }, p = "همه‌چیز را از دست دادم. اما اگر چیزی پیدا کنیم، امیدوارم Naj'kula باشد.", c = "<Ulantu looks through the lich's notes.>\nهمه‌شان این‌جاست، اما Naj'kula نیست..." }
WoWFQ[96451] = { t = "یک کودک از Ula'tek", d = "این را دوست ندارم. تا حالا باید پیدایش کرده بودیم.\n<Ulantu's face is sweaty and pale. She rubs her wound absentmindedly.>\nلیش باید او را کشانده باشد جایی که آزمایش‌هایش را می‌کرد. و اگر مدارکش درست بگویند...\nباید سریع Naj'kula را پیدا کنیم--وگرنه شاید دیگر آن کسی نباشد که بود.", o = { "Naj'kula را پیدا کن" }, c = "<Sweat beads on Ulantu's forehead. She growls slightly in pain and can now barely walk.>\nKuku... باید می‌فهمیدم. باید از این‌جا بیرون‌مان می‌کشیدم." }
WoWFQ[96457] = { t = "هیچ چیز نباید بماند", o = { "با گردن‌آویز آتش Naj'kula اشیای آزمایشگاه Lokago را نابود کن." } }
WoWFQ[96458] = { t = "آخرین پیمان", d = "Lokago مرا با همان زهری برید که Naj'kula را کج کرده. حس می‌کنم همین‌طور مرا می‌سوزاند.\nقصد دارم یک Amani بمیرم. اما کارم ناتمام است.\nلطفاً این یادداشت‌ها را به Kul'amara برسان.\nبه او بگو می‌تواند من را کنار Naj'kula پیدا کند.", o = { "Ulantu's Notes" }, p = "هر چه با هم گذشت...\nنمی‌شود بیهوده باشد.", c = "چه شده؟ ماجرای Ulantu و Naj'kula است؟\n<Kul'amara leafs through the pages. Her eyes widen.>\nممنون که این را آوردی، hash'ura. دیده‌بان‌هایم رفته‌اند، اما اطلاعاتی که برایش جان دادند جان‌ها را نجات می‌دهد." }
WoWFQ[96467] = { t = "تشنگی دانش", d = "دو برادر همراه ما به این مکان نفرین‌شده آمدند... Zei'ka و Jun'ka.\nZei'ka آتش در وجودش بود. همین که پیاده شدیم دوید، دنبال زمزمه‌ها، انگار اسمش را صدا می‌زنند. اما Jun'ka احمق نیست. دنبال برادرش رفت تا نگذارد خودش را بکشد.\nاین را دوست ندارم. این جزیره اگر حواس‌مان نباشد ما را یک‌جا قورت می‌دهد. برو حالشان را بگیر، خب؟", c = "هی... Kul'amara زیادی نگران است. این جزیره نیامده ما را بترساند--آمده فهمیده شود!" }
WoWFQ[96469] = { t = "سردابه بی‌آبرویان", d = "Jun'ka برادرم است، اما آن‌قدر نگران است که نمی‌گذارد دنبال رؤیای زندگیم برود.\nاز بچگی می‌خواستم بیشتر دربارهٔ تاریخ‌مان بدانم. بیشترش را قصه‌گویان hometown می‌گویند، اما همیشه یک چیز را حذف می‌کردند: Atal'Utek. هر چه بیشتر کندوکاو کردم، مرموزتر شد و من مشغول‌تر.\nحالا دیده‌بان‌ها می‌گویند این سردابه پر از لوح است. لوح‌هایی که می‌توانند تاریخ قوم ما باشند. باید آن لوح‌ها را ببینم، حتی اگر جانم را بگیرد. هستی؟", o = { "دنبال Zei'ka برو", "مانع دور زده شد", "لوح را بخوان", "دنبال Zei'ka برو", "لوح‌ها را جمع کن" }, p = "چه معطل هستی! دانش در انتظار است!", c = "آهای! چرا دیوارها باید الان دقیقاً فرو بریزند؟!\nشما باید بروید... اما لوح‌ها!" }
WoWFQ[96471] = { t = "ریزش و غلتیدن", d = "به همه‌اش لعنت! به‌خاطر نگرانی برادرم از جنس خودم، شما را به این گِل کشیدم!\nسریع از این‌جا بیرون می‌روی! من جلو، تو دنبالم، عقب نمان وگرنه له می‌شوی!", o = { "از سردابه فرار کن" }, c = "ممنون... ممنون که با حماقت‌های Zei'ka کنار آمدی. از این‌که سالمی... خوشحالم.\n<Jun'ka chokes up.>\nحالا... حالا حواسم به من نباشد. کمی سکوت می‌خواهم... فقط تا فکرهایم را هضم کنم." }
WoWFQ[96474] = { t = "شکار: چیزی برای Astalor", d = "<Name>!\nآه، هنوز دیدار نکرده‌ایم. رسمی‌منشی. حین، خب، سابیدن کف‌ها، گوشه‌ای از گفت‌وگوهایت با Magister Astalor به گوشم خورد. به‌نظر اپراتور حسابی‌ای می‌آیی! این یعنی ما دوتا.\nمعمولاً.\nالان کمی... سرم شلوغ است، با این حیات وحش محل و باقی ماجرا.\nشاید بتوانی برایمان کمی گشتن بزنی؟", o = { "«سنگ» مرموز وارسی شد" }, p = "می‌توانیم برویم؟", c = "<Ethrandil sighs heavily.>\nالبته که ارواح هم هست." }
WoWFQ[96528] = { t = "شکار: رنج از آن‌سو", o = { "برای Sanctum Attendant Ethrandil گورِ نفرین‌شده را کاوش کن." } }
WoWFQ[96625] = { t = "گلادیاتورهای شبح‌مانند", d = "به میان میدان بیا! اهالی، چلنجری تازه داریم که فکر می‌کند از پس بهترین مبارزهای ما برمی‌آید!", o = { "مبارزان دشمن شکست‌خورده" }, c = "تأثیرگذار بود. چطور این‌همه آسیب زدی؟" }
WoWFQ[96639] = { t = "گشت‌زنی در معبد", d = "ایستادن بی‌کار کاری از پیش نمی‌برد. پشت قوی و چشم تیزی داری؛ بهتر است به کارشان بیاوری. نمی‌توانیم اجازه دهیم مارها یک وجب هم پیشرفت کنند.\nمعبد را گشت بزن. هر کس را دیدی که کمک می‌خواهد، کمکش کن. کسی را دیدی که دیگر نجات ندارد؟ مطمئن شو آن شیاطینی که به او زدند تاوان بدهند.", o = { "گشت‌های معبد کامل شد" }, c = "کار تمیز. اگر صد paladin دیگر مثل تو داشتم، معبد را در یک هفته پاک می‌کردیم." }
WoWFQ[96640] = { t = "غنیمتِ نفرین‌شدگان", d = "این معبد رازهای زیادی دارد، <name>. قدرت باستانی، که فقط منتظر است کسی آن را بردارد. Soulcoilerها ممکن است مرده باشند، اما قدرتشان مانده. انبارهایشان را پیدا کن و هر چه یافتی برایم بیاور.", o = { "Forgotten Relic" }, p = "چه پیدا کردی؟", c = "از کارهای خودِ Soulcoilerها برای پاک‌سازی‌شان استفاده می‌کنیم." }
WoWFQ[96641] = { t = "حمله‌های بی‌امان", d = "بعضی‌ها می‌گویند نیروهای Ula'tek بی‌پایان‌اند--این‌که هرگز نمی‌توان همه را کشت.\n<Socho grins.>\nاما من چالش را دوست دارم. تو چطور؟ محکم به دشمن بزن و ببینیم چقدر بی‌پایان‌اند.", o = { "حمله‌های معبد کامل شد" }, p = "جنگ را به سراغ دشمن ببر. یک ثانیه هم بهش استراحت نمی‌دهیم.", c = "این اولین جنگ تو نیست، این‌طور نیست؟ مارها پیش از تمام شدن ماجرا خواهند ترسیدت." }
WoWFQ[96642] = { t = "یورش‌های قطعی", d = "حمله‌ها فقط قدم اول است. نمی‌توانیم بگذاریم دشمن نفس بگیرد. اول می‌کوبیم، نرمشان می‌کنیم. بعد، با هر چه داریم محکم و سریع می‌زنیم.\nبرای یک نبرد طولانی نیرو نداریم. وقتی وقت یورش رسید، بهتر است آماده باشی.\nمتحدانت را جمع کن. دشمن Mighty است.", o = { "یورش معبد کامل شد" }, p = "برای یورش آماده‌ای؟", c = "آن نبرد لایق ترانه‌های قدیم بود! حالا می‌فهمم چرا Zul'jarra تو را دوست دارد." }
WoWFQ[96643] = { t = "از همان‌جا که آمد", d = "حسش می‌کنی؟ چیزهای کهنه‌ای در معبد کمین کرده‌اند، منتظر برخاستن دوباره. با صدای نبرد کشیده می‌شوند و مشتاق‌اند خشونت‌شان را به تو برسانند. یکی از این دشمنان باستانی را پیدا کن و مطمئن شو دیگر برنمی‌خیزد.", o = { "دشمن باستانی کشته‌شده" }, p = "حسش می‌کنی؟ آن خشونتی که فقط منتظر است بریزد بیرون؟", c = "تیغ‌هایت را تیز نگه دار. معبد هیچ‌وقت برای مدت طولانی نمی‌خوابد." }
WoWFQ[96644] = { t = "ذاتِ بدخواهی", d = "به زهر نیاز دارم؛ خالص و پرقدرت. زهری که از زمین بالا می‌آید خیلی رقیق است--با چیزهای دیگر آلوده. باید چشمهٔ همان مادهٔ ناپاک را پیدا کنی.\nژرفای خزانه‌ها را بگرد. زهرِ واقعی همان‌جاست.", o = { "Malefic Venom" }, p = "خب، پیدا کردی؟", c = "<Er'inye takes the vial, a wicked smile playing across her face.>\nآه، خوب کار کردی. حتی بیشتر از چیزی که امید داشتم." }
WoWFQ[96707] = { t = "در شکم هیولا", d = "تقریباً کل معبد را زیر و رو کردیم. هر چه ژرف‌تر می‌رویم، حمله‌های دسته خشن‌تر می‌شود. باید نزدیک باشیم.\nتقریباً رسیده‌ایم، <name>. باید کمی بیشتر استوار بمانیم. برای Dak'zor، و برای Zul'jan، و برای همهٔ کسانی که در این نبرد رنج کشیدند.", o = { "با Lady Liadrin صحبت کن", "حملهٔ نهایی را از سر گذراندی" }, c = "پایین کمین کرده. مطمئنم. شرارتش را از همین‌جا هم حس می‌کنم.\nنزدیک من بمان، <name>. من نورافکن‌مان در برابر تاریکی Kith'ix خواهم بود." }
WoWFQ[96995] = { t = "پس زدن موج", d = "معبد دیگر طاقت خشم Ula'tek را ندارد. جسورترین زادگانش همه‌جا در جزیره ریخته‌اند! اگر جلوی سیل زهر را نگیریم همه‌مان را نابود می‌کنند.\nهر جا جرئت کردند سرشان را نشان بدهند با آن‌ها بجنگ. نگذارید جای پا پیدا کنند.", o = { "Curse Surge شکست‌خورده" }, p = "باید زنده بمانیم.", c = "این مدتی آن‌ها را عقب نگه می‌دارد... تا موج بعدی یعنی.\n<Zela regards you grimly.>\nغافلگیر نشو." }
WoWFQ[97482] = { t = "نیش، برای خاطره‌ها", d = "آن هیولای مار بی‌رحمانه بود، با زهری به‌قدر کافی قوی که سنگ را می‌خورد.\nقبل از فکر کردن به چنگ زدن بهش، باید مطمئن شویم بهترین تجهیزات ممکن را داریم.\nالبته چند ایده برای به کار بستن همان زهر به سود خودمان دارم تا با پای پرشروع شروع کنیم.", o = { "Azta'rec کشته شد در Venomfall Deeps" }, p = "می‌بینیم چطور طعم داروی خودش را می‌پسندد.", c = "خوب کار کردی. یک جفت چکمهٔ عالی می‌سازد." }
WoWFQ[97640] = { t = "خزانه‌های Atal'Utek: یک سکه زیاد", d = "خوب به‌نظر نمی‌رسی، <name>.\n<As Abdumati examines you grimly, your heart starts pounding and your vision goes green. The weight of the coin in your pocket feels overwhelming.>\nپس چیزی از آن‌جا پیدا کردی، نه؟ خزانه‌ها پر از گنج است، بیشترش نفرین‌شده.\nبه آن روح‌جادوگر اعتمادی ندارم، اما همان که دیدی همهٔ رازهای این مکان نفرت‌انگیز را می‌داند. اگر کسی بتواند کمک کند، اوست.", o = { "Er'inye را پیدا کن" }, c = "وقتی سکه‌های خورنده سنگین‌ت کردند، بیا پیش من." }
WoWFQ[98343] = { t = "ماهیگیریِ زهر: دومینِ من", d = "پیش از این‌که بفرستمت شکار، باید با آن چه از خدمه‌ام مانده آشنا شوی.\nبیشترشان در غرق شدن کشتی هلاک شدند، البته. بعضی‌ها به مرداب افتادند. چند خیانتکار... خب، همین لحظه می‌رسیم به آن‌ها، نه؟\nاما نایب دوم وفادارم دارد قلعه را سر پا نگه می‌دارد، همان پایین رودخانه از جای من. او تو را درست و حسابی جا می‌اندازد.", o = { "با Second Mate Sluggs دیدار کن" }, c = "اوه، کاپیتان فرستاده؟ خب، چه س-سورپرایز خوشایندی." }
WoWFQ[98388] = { t = "به درون خزانه‌های Atal'Utek", d = "پشت این سنگر، چیزی جز مار، روح، و مرگی زهرآگین نیست.\nاین هفته سه ستوان از دست دادم. قوی‌ها. شجاع‌ها. شاید از تو هم قوی‌تر و شجاع‌تر.\n<Warleader Abdumati looks you over with a weary eye.>\nاگر می‌خواهی خودت را به پرتگاه بیندازی، تشریف ببر. دیده‌بان‌هایم را برگردان، اگر توانستی میان استخوان‌ها پیدایشان کنی.\nاما مواظب قدم‌هایت باش. آن زهر آدم را یک‌جا قورت می‌دهد.", o = { "سوار Spiritwing Gust شو", "Naz'ara the Clever را نجات بده", "برای فرار از Spiritwing Feather استفاده کن", "از یک Windcaller بخواه به Eastern Amani Outpost پرواز کند", "از یک Windcaller بخواه پنهانت کند", "Hawkeye Socho را نجات بده", "از یک Windcaller بخواه به Northern Amani Bulwark پرواز کند", "Commander Gazba را نجات بده", "سکهٔ مرموز پیدا شد", "در Amani Foothold به Warleader Abdumati گزارش بده." }, p = "کاری نکن کسی را برای نجات تو بفرستم. جنگجوی آن‌قدر برای این کار ندارم.", c = "خب... دو تا از سه تا بد نیست، این‌جا به آن‌جا.\nاما کمی سبزرنگ به‌نظر می‌رسی. مطمئنی آن زهر نرفته تویت؟" }
WoWFQ[98419] = { t = "سرِ شانه به شانه", d = "خزانه‌ها جای خطرناکی است. عده‌ای جنگجوی شجاع و لجوج فکر می‌کنند به‌تنهایی از پس کودکان Ula'tek برمی‌آیند. اگر شانس بیاورند، قبل از این‌که بخورده شوند جسدشان را جمع می‌کنیم.\nمن تو را دوست دارم، <name>. حیف می‌شود یک مار تو را برای بچه‌هایش بفرستد. پس عاقل باش. افرادی پیدا کن که از پشتت مراقبت کنند، بعد با هم از میان معبد راه باز کن.", o = { "کشتن دشمنان در حالت پارتی" }, p = "این یک جنگ است، <name>. هیچ‌کس نباید تنها بجنگد.", c = "سرِ شانه به شانه. این‌طوری این نبرد را می‌بریم." }
WoWFQ[98420] = { t = "بیرون آن‌جا چه خبر است؟", d = "دانش مهم‌ترین سلاح در جنگ است. این خزانه‌ها باستانی و وسیع‌اند--دیده‌بان‌هایمان نمی‌توانند همه‌جا را ببینند. در ژرفای این تالارهای آلوده چه کمین کرده؟\nدقیقاً همین را باید بدانم. برو بیرون و بگو چه می‌بینی، اما تنها رفتن خطر دارد. بهتر است چند هم‌سفر بیاوری اگر می‌خواهی برگردی.", c = "این شیاطین فکر می‌کنند می‌توانند در تاریکی کمین کنند و نقشه بکشند. از لانه بیرونشان می‌کشیم و از این سرزمین‌ها پاکشان می‌کنیم." }
WoWFQ[98428] = { t = "خزانه‌های Atal'Utek: محراب زنگار", d = "محراب زنگار.\nچه کسی می‌داند این تکه سنگ نفرین‌شده چه وقت از زهر برخاست؟ عمرهاست مطالعه‌اش می‌کنم و تازه چشیده‌ام از قدرتش.\n<Er'inye licks her spectral lips.>\nفقط بگو و من زنگاری را که با خودت داری به چیز مفیدتری تبدیل می‌کنم. بعد می‌توانی با محراب هم‌آوا شوی و هدیه‌های فراوانش را بپذیری.", o = { "با Er'inye صحبت کن تا روحت زنگار بگیرد", "با محراب هم‌آوا شو" }, p = "این نفرین همه‌مان را به شیوه‌های مختلف می‌گیرد.", c = "چه حسی دارد؟ ماورایی؟ اغراق‌آمیز؟\nحاضرم خیلی چیزها را بدهم تا بتوانم دوباره برای اولین بار مزه‌اش کنم." }
WoWFQ[98515] = { t = "خزانه‌های Atal'Utek: تورِ سمی", o = { "یک گشت، یک حمله و یک یورش را کامل کن و یک دشمن باستانی را در Vaults of Atal'Utek شکست بده." } }
